INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmttxwd1z004ztqx3timw9q73', 'cmtrwv4au0004tqdpqikux9nr', 1, '{"text": "<p>Metro Yazılım; strateji, tasarım ve mühendisliği bir araya getirerek markaların dijital deneyimini uçtan uca kuruyor. Kısa vadeli çözümler değil, ölçeklenen ve zamanla büyüyen ürünler üretiyoruz.</p><p>İlk toplantıdan yayına kadar tek bir ekip: problemi anlar, doğru teknolojiyi seçer ve zarif, sürdürülebilir çözümler teslim ederiz.</p>", "banner": "Hakkımızda", "marquee": ["Özel Yazılım", "Yapay Zekâ", "E-Ticaret"], "features": [{"text": "Girişimden kurumsala uçtan uca teslim edilen dijital ürünler.", "title": "20+ tamamlanan proje"}, {"text": "Dört kıtadaki ekiplerimizle teknolojiyi ihtiyaca göre şekillendiriyoruz.", "title": "6 global ofis"}], "seoTitle": "Hakkımızda | Metro Yazılım", "subtitle": "Hakkımızda", "teamTitle": "İnovasyonun arkasındaki yüzler", "authorName": "Muhammet Berat Arslan", "authorRole": "CEO ve Yazılım Geliştirici", "collageAlt": "Metro Yazılım ekibi", "titleAfter": "dönüştüren bir ekip", "titleAccent": "ürünlere", "titleBefore": "Teknolojiyi işe yarar", "teamSubtitle": "Ekibimiz", "offeringTitle": "Uçtan uca dijital çözümler", "experienceUnit": "yıl", "offeringLabels": ["Web", "Mobil", "E-Ticaret", "Yapay Zekâ", "Bakım"], "seoDescription": "Metro Yazılım, özel yazılım, web siteleri, e-ticaret altyapıları, yapay zekâ otomasyonları geliştirerek işletmeleri daha hızlı, verimli ve yönetilebilir kılar.", "experienceLabel": "deneyim", "experienceValue": "1", "offeringSubtitle": "Sunduklarımız", "authorImageAssetId": null, "collageImageAssetId": null}', '2026-09-09 10:12:34.2', 'cmts0wj9r0000tqzz9audivoc');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmttxwd260055tqx3bl6cui5g', 'cmtr7cl6t0006tqqp50dcn075', 1, '{"cta": {"url": "/iletisim", "label": "Teklif Al"}, "brand": {"name": "Metro Yazılım", "logoAssetId": null}, "footer": {"columns": [], "summary": "Metro Yazılım; özel yazılım, web siteleri, e-ticaret altyapıları ve yapay zekâ otomasyonları geliştirerek işletmeleri daha hızlı, verimli ve yönetilebilir kılar."}, "vision": "Extech vision statement.", "contact": {"email": "info@metroyazilim.com", "phone": "+90 530 251 88 30", "address": "Levent, İstanbul 34394"}, "mission": "Extech mission statement.", "termsBody": "<p>terms-e2e-959102a2</p>", "navigation": [], "privacyBody": "<p>Kişisel verileriniz yalnızca hizmetlerimizi sunmak amacıyla işlenir ve üçüncü taraflarla paylaşılmaz.</p>"}', '2026-09-09 10:12:34.206', 'cmts0wj9r0000tqzz9audivoc');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmttco7bp0001tq8bvfj7eujw', 'cmtpkwkq2002qtq549fil5pab', 1, '{"blocks": [{"id": "services-heading", "html": "<h2>Teknolojiyle BT Sorunlarını Çözüyoruz</h2><p>Ne Yapıyoruz: Güvenilir altyapı ve uzman ekiple işinizi bir adım öteye taşıyoruz.</p>", "type": "text", "visible": true}, {"id": "service-item-1", "cta": {"href": "/tr/services", "label": "Devamını Oku"}, "body": "<p>Güvenilir altyapı ve uzman ekiple işinizi bir adım öteye taşıyoruz.</p>", "type": "banner", "title": "Veritabanı Güvenliği", "visible": true, "mediaAssetId": null}, {"id": "service-item-2", "cta": {"href": "/tr/services", "label": "Devamını Oku"}, "body": "<p>Güvenilir altyapı ve uzman ekiple işinizi bir adım öteye taşıyoruz.</p>", "type": "banner", "title": "BT Danışmanlığı", "visible": true, "mediaAssetId": null}, {"id": "service-item-3", "cta": {"href": "/tr/services", "label": "Devamını Oku"}, "body": "<p>Güvenilir altyapı ve uzman ekiple işinizi bir adım öteye taşıyoruz.</p>", "type": "banner", "title": "Uygulama Geliştirme", "visible": true, "mediaAssetId": null}, {"id": "service-item-4", "cta": {"href": "/tr/services", "label": "Devamını Oku"}, "body": "<p>Güvenilir altyapı ve uzman ekiple işinizi bir adım öteye taşıyoruz.</p>", "type": "banner", "title": "Bulut Altyapı Çözümleri", "visible": true, "mediaAssetId": null}], "widget": {"limit": 2, "title": "dsa", "layout": "carousel", "bgImage": null, "columns": "2", "subtitle": "dsada", "kpiVariant": "counter-grid", "cardVariant": "standard", "selectedEntityIds": ["cmtq8to3h0002tq2dgsgbhn5o", "cmtsbphsz000gtqfrcofct0zo"]}}', '2026-09-09 00:18:21.589', 'cmts0wj9r0000tqzz9audivoc');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtty1fg80001tquvmeq45i80', 'cmttxvilc0002tq02g034xsr9', 2, '{"icon": null, "slug": "ozel-yazilim-gelistirme-hizmetleri", "title": "Özel Yazılım Geliştirme Hizmetleri", "blocks": [{"id": "b1", "html": "<p>Özel yazılım geliştirme, işletmelerin ihtiyaçlarına ve çalışma süreçlerine özel yazılım çözümleri sunma sürecidir. Hazır yazılımlar genellikle standart iş süreçlerine hitap ederken, özel yazılım projeleri, işletmenin benzersiz gereksinimlerini karşılamak üzere tasarlanır. Bu hizmet, işletmelerin verimliliğini arttırmak, süreçlerini optimize etmek ve rekabet avantajı sağlamak amacıyla tercih edilir.</p><p>Proje sonunda, müşterilerimize kapsamlı bir sistem dokümantasyonu, kaynak kodları ve gerekli yönetim erişimleri sağlıyoruz. Bu, yazılımı daha iyi anlayabilmeniz ve gerektiğinde değişiklik yapabilmeniz için kritik öneme sahiptir. Ayrıca, projenin tüm aşamalarında sağlanan teknik destekle, yazılımın uzun ömürlü ve sürdürülebilir olması için gerekli adımları atıyoruz.</p>", "type": "text"}, {"id": "b2", "html": "<h3>Kimler için uygun</h3><ul><li>Hazır yazılımların yetersiz kaldığı işletmeler</li><li>Girişimciler ve startup''lar</li><li>KOBİ''ler</li><li>Kurumsal firmalar</li><li>Özel süreçleri olan sektörler</li></ul>", "type": "text"}, {"id": "b3", "html": "<h3>Neleri kapsıyor</h3><ul><li>Yönetim panelleri</li><li>CRM sistemleri</li><li>İş takip uygulamaları</li><li>Rezervasyon sistemleri</li><li>Muhasebe ve operasyon yazılımları</li><li>API entegrasyonları</li><li>Web ve mobil tabanlı özel projeler</li></ul>", "type": "text"}, {"id": "b4", "html": "<h3>Nasıl çalışıyoruz</h3><ul><li>İhtiyaç Analizi: İşletmenizin ihtiyaçlarını ve mevcut çalışma süreçlerini analiz ediyoruz.</li><li>Proje Tanımı: Projenin kapsamını, kullanıcı rollerini ve temel özelliklerini belirliyoruz.</li><li>Tasarım Süreci: Kullanıcı dostu arayüz ve yönetim paneli tasarlıyoruz.</li><li>Backend Geliştirme: Güvenli ve ölçeklenebilir backend altyapısı geliştiriyoruz.</li><li>Entegrasyon: Gerekli üçüncü taraf servisleri ve API sistemlerini entegre ediyoruz.</li><li>Uyumlu Geliştirme: Yazılımı masaüstü, tablet ve mobil cihazlarla uyumlu geliştiriyoruz.</li><li>Test ve Güvenlik: Test, güvenlik ve performans kontrollerini gerçekleştiriyoruz.</li><li>Yayınlama Süreci: Yazılımın sunucuya kurulması ve canlıya alınması süreçlerini yürütüyoruz.</li><li>Destek ve Bakım: Proje tesliminden sonra bakım, geliştirme ve teknik destek sağlıyoruz.</li><li>Dokümantasyon: Müşteriye kaynak kod, sistem dokümantasyonu ve yönetim erişimleri teslim ediliyor.</li></ul>", "type": "text"}, {"id": "b5", "html": "<h3>Kullandığımız teknolojiler</h3><ul><li>Next.js: Hızlı ve kullanıcı dostu web uygulamaları geliştirmek için kullanılır.</li><li>React: Arayüz geliştirme için güçlü bir kütüphanedir.</li><li>Node.js: Sunucu tarafında JavaScript çalıştırarak verimli uygulamalar oluşturur.</li><li>NestJS: Modern ve ölçeklenebilir sunucu uygulamaları geliştirmek için kullanılır.</li><li>TypeScript: JavaScript''in güçlü bir biçimlendirilmiş sürümüdür, büyük projelerde hata önleme sağlar.</li><li>PostgreSQL: Güçlü bir açık kaynaklı veritabanıdır, veri güvenliğini artırır.</li><li>MongoDB: NoSQL veritabanı, esnek veri yapıları sunar.</li><li>Redis: Hızlı veri erişimi sağlayan bir bellek içi veritabanıdır.</li><li>Docker: Uygulamaların taşınabilirliğini ve yönetimini kolaylaştırır.</li><li>Bulut Servisleri: Ölçeklenebilir ve erişilebilir altyapı sunar.</li></ul>", "type": "text"}], "summary": "İşletmenizin ihtiyaçlarına ve hedeflerine özel; güvenli, ölçeklenebilir ve sürdürülebilir yazılım çözümleri geliştiriyoruz.", "seoTitle": "Özel Yazılım Geliştirme Hizmetleri | Metro Yazılım", "imageAssetId": null, "seoDescription": "Metro Yazılım, işletmenizin ihtiyaçlarına özel yazılım çözümleri sunar. Güvenli, ölçeklenebilir ve yönetilebilir yazılımlar geliştirin."}', '2026-09-09 10:16:30.585', 'cmts0wj9r0000tqzz9audivoc');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtty1fgj0009tquvbpb10yva', 'cmttxvilt000dtq02w71frytv', 2, '{"icon": null, "slug": "web-uygulama-gelistirme", "title": "Web Uygulama Geliştirme", "blocks": [{"id": "b6", "html": "<p>Web uygulama geliştirme, işletmelerin internet üzerinden iş süreçlerini yönetmelerine yardımcı olan önemli bir hizmettir. İyi tasarlanmış bir web uygulaması, kullanıcıların ihtiyaçlarına göre özelleştirilmiş çözümler sunarak, iş verimliliğini artırır. Tarayıcı tabanlı çalışan bu uygulamalar, hızlı, güvenli ve mobil uyumlu bir deneyim sağlar.</p><p>Proje tamamlandığında, kullanıcıların ihtiyaçlarını karşılayacak bir web uygulaması, yönetim paneli ve gerekli tüm entegrasyonlar hazır hale gelir. Kullanıcılar, sistem verilerine erişim sağlayabilir, içerik güncellemeleri yapabilir ve performans raporlarına ulaşabilirler.</p>", "type": "text"}, {"id": "b7", "html": "<h3>Kimler için uygun</h3><ul><li>İş süreçlerini internet üzerinden yönetmek isteyen işletmeler</li><li>Girişimler ve yeni projeler geliştiren girişimciler</li><li>E-ticaret firmaları ve online satış platformları</li><li>Kurumsal şirketler ve yöneticiler</li></ul>", "type": "text"}, {"id": "b8", "html": "<h3>Neleri kapsıyor</h3><ul><li>Kurumsal yönetim panelleri</li><li>Müşteri portalları</li><li>Rezervasyon sistemleri</li><li>CRM uygulamaları</li><li>SaaS projeleri</li><li>Raporlama ekranları</li><li>Bayi sistemleri ve özel web platformları</li></ul>", "type": "text"}, {"id": "b9", "html": "<h3>Nasıl çalışıyoruz</h3><ul><li>İhtiyaç Analizi: Projenin kullanıcılarını, rollerini ve temel kullanım senaryolarını belirliyoruz.</li><li>Arayüz Tasarımı: Mobil, tablet ve masaüstü cihazlara uyumlu arayüz tasarımı yapıyoruz.</li><li>Geliştirme: Hızlı açılan ve arama motorları tarafından okunabilen sayfalar geliştiriyoruz.</li><li>Yetkilendirme Sistemleri: Kullanıcı, yetkilendirme ve rol bazlı erişim sistemleri oluşturuyoruz.</li><li>API ve Veritabanı: Güvenli API ve veritabanı altyapısı geliştiriyoruz.</li><li>Entegrasyonlar: Ödeme, kargo, e-posta, SMS ve harici servis entegrasyonları yapıyoruz.</li><li>Yönetim Paneli: Yönetim panelinden içerik ve sistem verilerinin kontrol edilmesini sağlıyoruz.</li><li>Test Süreçleri: Performans, güvenlik ve kullanıcı deneyimi testleri gerçekleştiriyoruz.</li><li>Yayınlama: Web uygulamasını sunucuya kuruyor ve alan adı bağlantılarını tamamlıyoruz.</li><li>Bakım ve Destek: Projenin bakım, güncelleme ve yeni özellik geliştirme süreçlerini destekliyoruz.</li></ul>", "type": "text"}, {"id": "b10", "html": "<h3>Kullandığımız teknolojiler</h3><ul><li>Next.js: Sunucu tarafı renderlama ve statik site oluşturma için kullanılır.</li><li>React: Kullanıcı ara yüzleri geliştirmek için kullanılan bir kütüphanedir.</li><li>TypeScript: JavaScript''in tip güvenli bir hale getirilmesini sağlar.</li><li>Node.js: Sunucu tarafında JavaScript çalıştırmak için kullanılır.</li><li>NestJS: Sunucu uygulamaları için yapılandırılmış bir framework''tür.</li><li>PostgreSQL: Güçlü bir veritabanı yönetim sistemidir.</li><li>MongoDB: NoSQL veritabanı için kullanılır.</li><li>Redis: Hızlı veri erişimi için bir in-memory veri yapısıdır.</li><li>REST API: Sistemler arası iletişim sağlar.</li><li>Docker: Uygulamaların sanal ortamlarda çalıştırılmasını sağlar.</li><li>Cloudflare: Web uygulamalarını hızlandırmak ve güvenliğini artırmak için kullanılır.</li></ul>", "type": "text"}], "summary": "İş süreçlerinizi dijital ortamda kolayca yönetmenizi sağlayan; hızlı, güvenli, kullanıcı dostu ve ölçeklenebilir web uygulamaları geliştiriyoruz.", "seoTitle": "Web Uygulama Geliştirme | Metro Yazılım", "imageAssetId": null, "seoDescription": "Metro Yazılım ile profesyonel web uygulama geliştirme hizmetleri alarak iş süreçlerinizi hızlandırın. Hızlı ve güvenli çözümler sunuyoruz."}', '2026-09-09 10:16:30.596', 'cmts0wj9r0000tqzz9audivoc');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtty1fgq000htquvcns85c50', 'cmttxvim2000otq02vsld5hem', 2, '{"icon": null, "slug": "mobil-uygulama-gelistirme-hizmetleri", "title": "Mobil Uygulama Geliştirme Hizmetleri", "blocks": [{"id": "b11", "html": "<p>Mobil uygulama geliştirme, işletmelerin ve girişimcilerin ürün veya hizmetlerini mobil cihazlara taşımasını sağlayan bir süreçtir. Günümüzde mobil uygulamaların önemi giderek artmakta, kullanıcı deneyimini iyileştiren ve etkileşimi artıran çözümler sunulmaktadır. Metro Yazılım olarak, kullanıcı odaklı, hızlı ve güvenli mobil uygulamalar tasarlıyor ve geliştiriyoruz.</p><p>Mobil uygulama geliştirme sürecinin sonunda, kullanıcı dostu, hızlı ve güvenli bir mobil uygulama teslim ediyoruz. Ayrıca, entegre bir yönetim paneli ile kullanıcı ve içerik yönetimi süreçlerini kolaylaştırıyoruz. Uygulamanız, hem App Store hem de Google Play''de yayınlanmaya hazır bir şekilde sunulmaktadır.</p>", "type": "text"}, {"id": "b12", "html": "<h3>Kimler için uygun</h3><ul><li>Ürün veya hizmetlerini mobil cihazlara taşımak isteyen işletmeler</li><li>Startup ve girişimciler</li><li>E-ticaret firmaları</li><li>Hizmet sağlayıcılar</li><li>Kurumsal firmalar ve çalışanları için mobil çözümler arayanlar</li></ul>", "type": "text"}, {"id": "b13", "html": "<h3>Neleri kapsıyor</h3><ul><li>E-ticaret uygulamaları</li><li>Rezervasyon uygulamaları</li><li>Kurumsal uygulamalar</li><li>Müşteri uygulamaları</li><li>Saha ekipleri için mobil sistemler</li><li>Üyelik ve abonelik uygulamaları</li></ul>", "type": "text"}, {"id": "b14", "html": "<h3>Nasıl çalışıyoruz</h3><ul><li>Mobil uygulama fikrini ve hedef kullanıcı kitlesini analiz ediyoruz.</li><li>Uygulamanın temel özelliklerini ve kullanıcı akışlarını belirliyoruz.</li><li>iOS ve Android için ortak kod tabanlı çözümler geliştiriyoruz.</li><li>Modern ve kullanıcı dostu mobil arayüzler tasarlıyoruz.</li><li>Kullanıcı kaydı, giriş ve yetkilendirme sistemlerini oluşturuyoruz.</li><li>Bildirim, konum, kamera, ödeme ve dosya yükleme özelliklerini entegre ediyoruz.</li><li>Mobil uygulamayı yönetmek için web tabanlı yönetim paneli geliştiriyoruz.</li><li>Backend API ve veritabanı altyapısını hazırlıyoruz.</li><li>Farklı ekran boyutları ve cihazlarda uygulamayı test ediyoruz.</li><li>Performans, veri güvenliği ve hata kontrollerini gerçekleştiriyoruz.</li><li>App Store ve Google Play yayın süreçlerinde destek sağlıyoruz.</li><li>Yayın sonrasında bakım, güncelleme ve yeni özellik geliştirme hizmeti veriyoruz.</li></ul>", "type": "text"}, {"id": "b15", "html": "<h3>Kullandığımız teknolojiler</h3><ul><li>Flutter: Hem iOS hem de Android için hızlı ve etkili uygulama geliştirme aracı.</li><li>React Native: Çapraz platform uygulama geliştirme için kullanılan bir framework.</li><li>Firebase: Gerçek zamanlı veritabanı ve kullanıcı kimlik doğrulama hizmetleri sunar.</li><li>Node.js: Sunucu tarafında hızlı ve ölçeklenebilir uygulamalar geliştirmek için kullanılır.</li><li>NestJS: Güçlü bir sunucu uygulaması framework''ü.</li><li>TypeScript: JavaScript''in üst kümesi, uygulama geliştirmeyi daha güvenli hale getirir.</li><li>PostgreSQL: Güçlü ve güvenilir bir ilişkisel veritabanı yönetim sistemi.</li><li>REST API: Uygulamalar arasında veri alışverişi için standart bir yöntem.</li><li>Bulut servisleri: Uygulamalarınızı barındırmak ve ölçeklendirmek için esnek çözümler sunar.</li></ul>", "type": "text"}], "summary": "iOS ve Android cihazlarda yüksek performanslı, güvenli ve kullanıcı odaklı mobil uygulamalar geliştiriyoruz. Fikir aşamasından mağaza yayınına ve bakım süreçlerine kadar tüm süreci yönetiyoruz.", "seoTitle": "Mobil Uygulama Geliştirme | Metro Yazılım", "imageAssetId": null, "seoDescription": "Metro Yazılım, iOS ve Android için modern mobil uygulama geliştirme hizmetleri sunar. İşletmenizi mobil platforma taşıyın."}', '2026-09-09 10:16:30.603', 'cmts0wj9r0000tqzz9audivoc');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmts0wjlh00j8tqzzyo5gsjol', 'cmtrwv4au0004tqdpqikux9nr', 1, '{"text": "Deneyimli ekibimiz, doğru stratejiler ve güncel teknolojilerle işletmenizin büyümesine katkı sağlar.", "banner": "Hakkımızda", "marquee": ["Siber Güvenlik", "BT Çözümü", "Teknoloji", "Veri Güvenliği"], "features": [{"text": "Karmaşık sorunlara hızlı ve kalıcı çözümler üretiyoruz.", "title": "Sorun Çözme"}, {"text": "Teknolojiyle geleceği bugünden şekillendiriyoruz.", "title": "Misyon & Vizyon"}], "seoTitle": null, "subtitle": "HAKKIMIZDA", "teamTitle": "Özverili Ekip Üyelerimiz", "authorName": "Kaan Aksoy", "authorRole": "Kurucu Ortak", "collageAlt": "Metro Yazılım uzmanları çalışırken", "titleAfter": "Artırıyoruz", "titleAccent": "Teknolojiyle", "titleBefore": "İş Başarımızı", "teamSubtitle": "Ekip Üyeleri", "offeringTitle": "Teknoloji Trendleriyle Öncü Olun", "experienceUnit": "Yıllık", "offeringLabels": ["Web Sitesi", "Android", "iOS", "Akıllı Saat", "IoT"], "seoDescription": null, "experienceLabel": "Deneyim", "experienceValue": "25", "offeringSubtitle": "Sunduklarımız", "authorImageAssetId": null, "collageImageAssetId": null}', '2026-09-08 02:01:09.173', 'cmts0wj9r0000tqzz9audivoc');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmts0xghh001qtq9zo642stkq', 'cmtr7cl6t0006tqqp50dcn075', 1, '{"cta": {"url": null, "label": null}, "brand": {"name": "Metro Yazılım", "logoAssetId": null}, "footer": {"columns": [], "summary": "Veritabanı güvenliği, BT danışmanlığı ve bulut altyapı çözümleriyle işletmenizin büyümesine katkı sağlıyoruz."}, "vision": "Bölgesinde teknoloji ortağı olarak tercih edilen, yenilikçi çözümleriyle öne çıkan güvenilir bir BT şirketi olmak.", "contact": {"email": "info@example.com", "phone": "+208-555-0112", "address": null}, "mission": "İşletmelerin güvenli, ölçeklenebilir ve sürdürülebilir teknolojilerle büyümesini sağlamak; her projede şeffaf iletişim ve ölçülebilir sonuçlarla değer üretmek.", "termsBody": "<p>Bu siteyi kullanarak aşağıdaki kullanım şartlarını kabul etmiş sayılırsınız. İçerikler önceden haber verilmeksizin güncellenebilir.</p>", "navigation": [], "privacyBody": "<p>Kişisel verileriniz yalnızca hizmetlerimizi sunmak amacıyla işlenir ve üçüncü taraflarla paylaşılmaz.</p>"}', '2026-09-08 02:01:51.798', 'cmts0wj9r0000tqzz9audivoc');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtty1fgy000ptquv96wbca6p', 'cmttxvime000ztq02oe5estzs', 2, '{"icon": null, "slug": "e-ticaret-yazilimi-gelistirme-hizmeti", "title": "E-ticaret Yazılımı Geliştirme Hizmeti", "blocks": [{"id": "b16", "html": "<p>E-ticaret yazılımı geliştirme hizmetimiz, internet üzerinden ürün satışı yapmak isteyen markalar, mağazalar, üreticiler, toptancılar ve büyüyen e-ticaret işletmeleri için özel olarak tasarlanmıştır. Bu hizmetle, işletmenizin ürün, stok, sipariş, ödeme, kargo ve müşteri süreçlerini tek bir sistem altında entegre ederek verimliliği artırmayı hedefliyoruz.</p><p>Proje sonunda müşterilerimiz, özel e-ticaret yazılımı ve yönetim paneli ile birlikte, sorunsuz bir şekilde ürün, stok, sipariş, ödeme ve kargo süreçlerini yönetebilecekleri bir altyapıya sahip olur. Ayrıca, kapsamlı raporlama ve analiz araçları ile işletmelerinin performansını takip edebilirler.</p>", "type": "text"}, {"id": "b17", "html": "<h3>Kimler için uygun</h3><ul><li>İnternetten ürün satmak isteyen markalar</li><li>Mağazalar ve perakendeciler</li><li>Üreticiler ve toptancılar</li><li>Büyüyen e-ticaret işletmeleri</li></ul>", "type": "text"}, {"id": "b18", "html": "<h3>Neleri kapsıyor</h3><ul><li>Özel e-ticaret sitesi geliştirme</li><li>Mobil e-ticaret uygulaması oluşturma</li><li>Yönetim paneli ile entegre sistemler</li><li>Ürün ve varyasyon yönetimi</li><li>Kampanya ve indirim yönetimi</li><li>Ödeme ve kargo entegrasyonu</li><li>Raporlama ve analiz ekranları</li></ul>", "type": "text"}, {"id": "b19", "html": "<h3>Nasıl çalışıyoruz</h3><ul><li>İhtiyaç Analizi: İşletmenizin ürün yapısını ve satış modelini detaylıca inceliyoruz.</li><li>Altyapı Oluşturma: Ürün, kategori, marka, koleksiyon ve varyasyon sistemlerini oluşturuyoruz.</li><li>Yönetim Üzerine Tasarım: Stok, fiyat, indirim, kupon ve kampanya yönetimi geliştiriyoruz.</li><li>Arayüz Tasarımı: Mobil uyumlu ve hızlı çalışan e-ticaret arayüzü tasarlıyoruz.</li><li>Fonksiyonel Özellikler: Sepet, favoriler, üyelik ve sipariş takip özelliklerini hazırlıyoruz.</li><li>Ödeme Entegrasyonu: İyzico, PayTR ve uygun ödeme sistemlerini entegre ediyoruz.</li><li>Kargo Entegrasyonu: Kargo firmaları ve teslimat seçenekleri için entegrasyon sağlıyoruz.</li><li>Müşteri Yönetimi: Sipariş, müşteri, iade ve destek süreçlerini yönetim paneline bağlıyoruz.</li><li>Çok Dilli Destek: Türkçe, İngilizce ve farklı dil seçeneklerini destekleyen altyapı kuruyoruz.</li><li>SEO ve Analiz: Teknik SEO, ürün şemaları ve arama motoru uyumlu sayfalar geliştiriyoruz.</li><li>Ölçüm ve Güvenlik: GA4, dönüşüm takibi ve reklam ölçümleme sistemlerini entegre ediyoruz.</li><li>Destek ve Yayın: Projenin sunucu kurulumu, yayına alınması ve teknik desteğini sağlıyoruz.</li></ul>", "type": "text"}, {"id": "b20", "html": "<h3>Kullandığımız teknolojiler</h3><ul><li>Next.js</li><li>React</li><li>Node.js</li><li>NestJS</li><li>PostgreSQL</li><li>Redis</li><li>Cloudflare</li><li>iyzico ve PayTR</li></ul>", "type": "text"}], "summary": "Markanızın dijital yolculuğunu güçlendiren; alışveriş, ödeme ve müşteri deneyimini kolaylaştıran modern e-ticaret çözümleriyle satışlarınızı artırıyoruz.", "seoTitle": "E-ticaret Yazılımı Geliştirme | Metro Yazılım", "imageAssetId": null, "seoDescription": "Metro Yazılım, özel e-ticaret yazılımı çözümleri ile işletmenizin süreçlerini tek bir platformda yönetmenizi sağlar. Hızlı ve güvenilir sistemler geliştirin."}', '2026-09-09 10:16:30.61', 'cmts0wj9r0000tqzz9audivoc');
