INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmttcs5r80001tqb1s5wgonwa', 'cmtpkwkq2002qtq549fil5pab', 1, '{"blocks": [{"id": "services-heading", "html": "<h2>Teknolojiyle BT Sorunlarını Çözüyoruz</h2><p>Ne Yapıyoruz: Güvenilir altyapı ve uzman ekiple işinizi bir adım öteye taşıyoruz.</p>", "type": "text", "visible": true}, {"id": "service-item-1", "cta": {"href": "/tr/services", "label": "Devamını Oku"}, "body": "<p>Güvenilir altyapı ve uzman ekiple işinizi bir adım öteye taşıyoruz.</p>", "type": "banner", "title": "Veritabanı Güvenliği", "visible": true, "mediaAssetId": null}, {"id": "service-item-2", "cta": {"href": "/tr/services", "label": "Devamını Oku"}, "body": "<p>Güvenilir altyapı ve uzman ekiple işinizi bir adım öteye taşıyoruz.</p>", "type": "banner", "title": "BT Danışmanlığı", "visible": true, "mediaAssetId": null}, {"id": "service-item-3", "cta": {"href": "/tr/services", "label": "Devamını Oku"}, "body": "<p>Güvenilir altyapı ve uzman ekiple işinizi bir adım öteye taşıyoruz.</p>", "type": "banner", "title": "Uygulama Geliştirme", "visible": true, "mediaAssetId": null}, {"id": "service-item-4", "cta": {"href": "/tr/services", "label": "Devamını Oku"}, "body": "<p>Güvenilir altyapı ve uzman ekiple işinizi bir adım öteye taşıyoruz.</p>", "type": "banner", "title": "Bulut Altyapı Çözümleri", "visible": true, "mediaAssetId": null}], "widget": {"limit": 4, "title": "", "layout": "grid-4", "bgImage": null, "columns": "4", "subtitle": "", "kpiVariant": "counter-grid", "cardVariant": "standard", "selectedEntityIds": []}}', '2026-09-09 00:21:26.18', 'system-reset');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtty1fh5000xtquva2fzdjyk', 'cmttxvimp001atq02fe4gfjx8', 2, '{"icon": null, "slug": "yapay-zeka-ve-is-sureci-otomasyonlari", "title": "Yapay Zekâ ve İş Süreci Otomasyonları", "blocks": [{"id": "b21", "html": "<p>Yapay zekâ ve iş süreci otomasyonları, işletmelerin verimliliğini artırmak ve zaman kaybını önlemek amacıyla tasarlanmıştır. Tekrarlanan ve zaman alan işlemleri otomatikleştirerek, işletmelerin operasyonlarını daha etkin bir şekilde yönetmelerine olanak tanır. Bu hizmet sayesinde, müşteri hizmetleri hızlanır ve iş süreçleri daha kontrol edilebilir hale gelir.</p><p>Hizmetlerimizi tamamladığımızda, işletmenizin ihtiyaçlarına özel olarak tasarlanmış otomasyon sistemleri elde edersiniz. Bu sistemler sayesinde, müşteri taleplerini daha hızlı yanıtlayarak müşteri memnuniyetinizi artırır, iş süreçlerinizi daha verimli yönetebilir ve zamandan tasarruf edersiniz.</p>", "type": "text"}, {"id": "b22", "html": "<h3>Kimler için uygun</h3><ul><li>Müşteri destek süreçlerini hızlandırmak isteyen işletmeler</li><li>Tekrarlayan işlemleri azaltmak isteyen şirketler</li><li>Verimlilik arayan kurumsal yapılar</li><li>Yapay zekâ ile süreçlerini optimize etmek isteyen tüm sektörler</li></ul>", "type": "text"}, {"id": "b23", "html": "<h3>Neleri kapsıyor</h3><ul><li>Web sitesi chatbotu geliştirme</li><li>Müşteri destek asistanlarının otomasyonu</li><li>İçerik üretim sistemleri</li><li>Teklif hazırlama otomasyonu</li><li>E-posta otomasyonu</li><li>Veri işleme ve raporlama çözümleri</li><li>CRM entegrasyonu</li><li>n8n üzerinden iş akışları oluşturma</li></ul>", "type": "text"}, {"id": "b24", "html": "<h3>Nasıl çalışıyoruz</h3><ul><li>İşletmedeki tekrarlanan ve zaman kaybettiren süreçleri tespit ediyoruz.</li><li>Otomasyona uygun iş adımlarını ve veri kaynaklarını belirliyoruz.</li><li>Web sitesine özel yapay zekâ destekli chatbot geliştiriyoruz.</li><li>Chatbotu işletmenin hizmetleri, ürünleri ve dokümanlarıyla özelleştiriyoruz.</li><li>Müşteri sorularını yanıtlayan ve talep toplayan sistemler oluşturuyoruz.</li><li>E-posta, form, CRM ve yönetim paneli süreçlerini otomatikleştiriyoruz.</li><li>n8n üzerinden çok adımlı otomasyon iş akışları kuruyoruz.</li><li>Yapay zekâ ile içerik, teklif, özet ve rapor üretimi sağlıyoruz.</li><li>Telegram, WhatsApp, web sitesi ve farklı platformlarla entegrasyon seçenekleri sunuyoruz.</li><li>İşlemlerin kayıt altına alınmasını ve yönetim panelinden takip edilmesini sağlıyoruz.</li><li>İnsan onayı gerektiren işlemler için kontrollü çalışma sistemi oluşturuyoruz.</li><li>Veri güvenliği, yetkilendirme ve kullanım maliyetlerini dikkate alıyoruz.</li><li>Kurulum sonrasında otomasyonların bakım ve geliştirme desteğini sağlıyoruz.</li></ul>", "type": "text"}, {"id": "b25", "html": "<h3>Kullandığımız teknolojiler</h3><ul><li>OpenAI API</li><li>Yapay Zekâ Modelleri</li><li>n8n</li><li>Node.js</li><li>REST API</li><li>Webhook</li><li>PostgreSQL</li><li>Redis</li><li>Özel Entegrasyonlar</li></ul>", "type": "text"}], "summary": "Yapay zekâ ve otomasyon teknolojileriyle tekrarlayan görevleri azaltıyor, operasyonel süreçlerinizi hızlandırıyor ve işinizi daha verimli yönetmenizi sağlıyoruz.", "seoTitle": "Yapay Zekâ ve İş Süreci Otomasyonları | Metro Yazılım", "imageAssetId": null, "seoDescription": "Yapay zekâ ve otomasyon çözümleriyle iş süreçlerinizi optimize edin. Verimliliği artırmanın yollarını keşfedin."}', '2026-09-09 10:16:30.617', 'cmts0wj9r0000tqzz9audivoc');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtty1fhd0015tquviw5c01sv', 'cmttxvin0001ltq02v660uzue', 2, '{"icon": null, "slug": "yazilim-bakim-ve-teknik-destek-hizmeti", "title": "Yazılım Bakım ve Teknik Destek Hizmeti", "blocks": [{"id": "b26", "html": "<p>Yazılım bakım ve teknik destek hizmetimiz, mevcut web siteniz, mobil uygulamanız veya özel yazılım sistemlerinizin güvenilir ve etkin bir şekilde çalışmasını sağlamak amacıyla sunulmaktadır. Bu hizmet, yazılımların teknik altyapısının kontrol edilmesi, güncellemelerin gerçekleştirilmesi ve oluşabilecek sorunların giderilmesi gibi çeşitli ihtiyaçlara cevap vermektedir.</p><p>Yazılım bakım ve teknik destek hizmetimiz sonucunda; güncellenmiş, güvenli ve performansı artırılmış bir yazılım sistemi elde edersiniz. Ayrıca, düzenli raporlar ile sisteminizin durumu hakkında bilgi sahibi olursunuz.</p>", "type": "text"}, {"id": "b27", "html": "<h3>Kimler için uygun</h3><ul><li>Mevcut web sitesi olan işletmeler</li><li>Mobil uygulama geliştiren firmalar</li><li>Online satış yapan e-ticaret sistemleri</li><li>Özel yazılım çözümleri kullanan şirketler</li></ul>", "type": "text"}, {"id": "b28", "html": "<h3>Neleri kapsıyor</h3><ul><li>Hata düzeltme ve sorun giderme</li><li>Performans iyileştirme</li><li>Güvenlik güncellemeleri</li><li>Sunucu yönetimi ve yapılandırması</li><li>Yedekleme ve geri yükleme süreçleri</li><li>Yeni özellik geliştirme</li><li>Entegrasyon bakımı ve destek</li><li>Teknik danışmanlık hizmetleri</li></ul>", "type": "text"}, {"id": "b29", "html": "<h3>Nasıl çalışıyoruz</h3><ul><li>Mevcut sistemin analizi: Yazılımın kod yapısını ve sunucu altyapısını inceliyoruz.</li><li>Hata ve güvenlik sorunlarının raporlanması: Tespit edilen sorunları detaylı bir şekilde raporluyoruz.</li><li>Güvenlik ve performans iyileştirmeleri: Çalışmayan veya hatalı özellikleri düzeltip, sayfa açılış hızını artırıyoruz.</li><li>Güncellemelerin yapılması: Yazılım paketlerini ve kullanılan teknolojileri kontrollü bir şekilde güncelliyoruz.</li><li>Veritabanı kontrolleri: Veritabanı performansını ve veri bütünlüğünü kontrol ediyoruz.</li><li>Sunucu yapılandırması: Sunucu, Docker, Nginx, SSL ve alan adı ayarlarını kontrol ediyoruz.</li><li>Güvenlik ayarlarının düzenlenmesi: Cloudflare, CDN ve önbellekleme ayarlarını optimize ediyoruz.</li><li>Yedekleme süreçlerinin planlanması: Yedekleme ve gerektiğinde geri yükleme süreçlerini oluşturuyoruz.</li><li>Entegrasyonların kontrolü: Ödeme, kargo ve diğer entegrasyonların düzgün çalışmasını sağlıyoruz.</li><li>Yeni özelliklerin eklenmesi: Mevcut sisteme yeni özellikler ve yönetim ekranları ekliyoruz.</li><li>Raporlama: Tüm işlemleri kayıt altına alıyor ve müşteriye detaylı rapor sunuyoruz.</li><li>Bakım hizmeti modeli: Aylık destek veya proje bazlı çalışma modeli ile esnek çözümler sunuyoruz.</li></ul>", "type": "text"}, {"id": "b30", "html": "<h3>Kullandığımız teknolojiler</h3><ul><li>Next.js</li><li>React</li><li>Node.js</li><li>NestJS</li><li>Flutter</li><li>PostgreSQL</li><li>MongoDB</li><li>Docker</li><li>Nginx</li><li>Cloudflare</li></ul>", "type": "text"}], "summary": "Yazılım sistemlerinizin güvenli, güncel ve kesintisiz çalışmasını sağlamak için bakım ve teknik destek hizmetleri sunuyoruz. Performans iyileştirmeleri, güvenlik güncellemeleri ve hata çözümleriyle sisteminizi sürekli aktif tutuyoruz.", "seoTitle": "Yazılım Bakım ve Teknik Destek | Metro Yazılım", "imageAssetId": null, "seoDescription": "Yazılım bakım hizmeti ile sistemlerinizin güvenliğini ve performansını artırın. Hata düzeltme, güncelleme ve teknik destek sunuyoruz."}', '2026-09-09 10:16:30.626', 'cmts0wj9r0000tqzz9audivoc');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtty1fhk001dtquv69laefnj', 'cmttxvin8001wtq0280iz25a8', 2, '{"slug": "voltstep-sports-cok-modullu-e-ticaret-platformu", "title": "VoltStep Sports: Çok Modüllü E-Ticaret Platformu", "client": null, "category": "E-Ticaret", "seoTitle": "VoltStep Sports: E-Ticaret Platformu Geliştirme", "seoDescription": "VoltStep Sports, çok modüllü e-ticaret platformu ile güvenli online alışveriş deneyimi sunar. Özel e-ticaret yazılımı ile geliştirilmiştir.", "solutionBlocks": [{"id": "b32", "html": "<p>VoltStep Sports, kapsamlı bir e-ticaret platformu olarak tasarlandı. Ürün, varyant ve stok yönetimi gibi kritik süreçleri tek bir altyapıda birleştiren bir sistem kuruldu. Bu sistem, dinamik olarak yönetilebilen ürün özellikleri ve kapsamlı bir veri yapısı sunarak kullanıcı ihtiyaçlarına cevap vermektedir.</p><p>VoltStep Sports, mobil uyumlu bir müşteri mağazası olarak React 19 ve Tailwind CSS ile geliştirilmiştir. Bu sayede, kullanıcılar her cihazdan rahatlıkla erişim sağlayabilir. Büyük ürün listelerinde performans sağlamak için sanallaştırılmış listeleme teknolojisi kullanılarak, sayfa yükleme süreleri minimuma indirilmiştir.</p><p>Proje, ölçeklenebilir bir yapıda merkezi backend mimarisi olarak NestJS tabanlı bir sistemle desteklenmiştir. PostgreSQL ve Prisma kullanılarak 40''tan fazla model içeren kapsamlı bir veri yapısı oluşturulmuştur. Ürünlerin dinamik yönetimi için EAV tabanlı öznitelik sistemi geliştirilmiştir. Böylece, ürünlere renk bazlı varyant, stok, fiyat ve görsel tanımlama altyapısı entegre edilmiştir.</p><p>Yönetim paneli, React 19, Vite ve TanStack Query kullanılarak geliştirilmiştir. Kullanıcılar, ürün ve kategori yönetimi, kampanya ve fiyatlandırma süreçlerini kolayca takip edebilir. Ayrıca, sürükle-bırak özellikleri ile kategori, marka, koleksiyon ve etiket yönetimi sağlanmıştır. Kritik işlemler, AuditLog ile kayıt altına alınarak güvenlik artırılmıştır.</p><p>Sepet ve sipariş oluşturma akışları, kullanıcıların alışveriş deneyimini kolaylaştırmak adına titizlikle geliştirilmiştir. PayTR entegrasyonu ile güvenli çevrimiçi ödeme altyapısı kurulmuştur. Ayrıca, satın alınan ürünler için değerlendirme ve yorum sistemi, kullanıcı geri bildirimlerinin toplanmasına olanak tanımaktadır. Sipariş sonrası iade ve değişim süreçleri de sisteme dahil edilerek esneklik sağlanmıştır.</p><p>Müşteri taleplerinin takip edilmesi için özel bir destek bileti sistemi oluşturulmuştur. Bu sistem, kullanıcıların sorularını ve sorunlarını hızlı bir şekilde iletebileceği bir platform sunmaktadır. Ayrıca, çoklu dil desteği için i18next tabanlı yerelleştirme sistemi ile birlikte, farklı dillerde hizmet verilmesi sağlanmıştır.</p><p>Kullanıcılara ve personele yönelik bildirim altyapısı geliştirilmiştir. Bu sistem sayesinde, önemli güncellemeler ve bildirimler anlık olarak iletilmektedir. Kullanıcılar, sipariş durumları hakkında bilgilendirilirken, personel kritik görevler için uyarılar alabilmektedir.</p><p>Projede, harici sistemlerin bağlanabilmesi için webhook altyapısı hazırlanmıştır. Swagger ile backend servislerinin API dokümantasyonu oluşturularak, geliştiricilerin API''ye erişimi kolaylaştırılmıştır. Ayrıca, PDF üretim sistemi ile sipariş belgeleri otomatik olarak oluşturulmaktadır.</p><p>Sonuç olarak, VoltStep Sports, farklı modülleri bir araya getiren, kullanıcı dostu ve kapsamlı bir e-ticaret platformu olarak teslim edilmiştir. Müşteri vitrininden yönetim paneline, backend API''den veri yapısına kadar tüm süreçler bir bütün halinde geliştirilmiş, tüm ihtiyaçlara cevap veren bir sistem ortaya konmuştur.</p>", "type": "text"}], "challengeBlocks": [{"id": "b31", "html": "<p>Müşteri, mevcut e-ticaret sisteminin sınırlı özellikleri nedeniyle verimliliğini artırmayı ve kullanıcı deneyimini iyileştirmeyi hedefliyordu. Ürün, varyant, stok, kampanya ve ödeme süreçlerinin entegre bir yapı içerisinde yönetilmesi gerekmekteydi. Kullanıcıların satın alma sonrası iade ve değişim süreçlerini kolayca gerçekleştirebilmesi için güçlü bir sistemin kurulması da önemli bir ihtiyaç olarak belirlendi.</p>", "type": "text"}], "galleryAssetIds": [], "coverImageAssetId": null}', '2026-09-09 10:16:30.632', 'cmts0wj9r0000tqzz9audivoc');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtty1fhq001ltquv2rjh7x90', 'cmttxving0027tq02nqxm8pth', 2, '{"slug": "patisca-mobil-e-ticaret-uygulamasi", "title": "Patisca Mobil E-Ticaret Uygulaması", "client": "Patisca", "category": "Mobil Uygulama", "seoTitle": "Patisca Mobil E-Ticaret Uygulaması | Metro Yazılım", "seoDescription": "Metro Yazılım, Patisca markası için iOS ve Android platformlarında mobil e-ticaret uygulaması geliştirdi. Tesettür giyim sektörüne yönelik çözümler sunuyor.", "solutionBlocks": [{"id": "b34", "html": "<p>Metro Yazılım, Patisca projesinde kullanıcıların ihtiyaçlarına yönelik bir mobil e-ticaret uygulaması geliştirmiştir. Uygulama, kullanıcı deneyimini ön planda tutarak tasarlanmış olup, ürünlerin renk ve beden varyasyonları ile birlikte rahatça seçilebilmesini sağlamaktadır. Ayrıca, kullanıcıların sepetlerine ürün eklemesi ve sipariş oluşturması süreçlerini de kolaylaştıran bir yapı kurulmuştur.</p><p>Patisca mobil uygulaması, Flutter ve Dart kullanılarak geliştirilmiştir. Flutter, yüksek performans sunan bir framework olarak hem iOS hem de Android platformlarında uygulama geliştirmeyi kolaylaştırmaktadır. Uygulamanın durum yönetiminde ise GetX kütüphanesi kullanılarak, uygulamanın durumu etkili bir şekilde yönetilmiştir.</p><p>Kullanıcıların uygulamaya kolayca kaydolabilmesi ve giriş yapabilmesi için Firebase Authentication kullanılmıştır. Bu teknoloji, güvenli bir kullanıcı deneyimi sunmakta ve kimlik doğrulama işlemlerini hızlı bir şekilde gerçekleştirmektedir.</p><p>Ürün, kategori, banner, kullanıcı ve sipariş verileri için Cloud Firestore kullanılmıştır. Bu veritabanı, gerçek zamanlı veri senkronizasyonu sağlamakla birlikte, uygulamanın performansını artırmaktadır. Ürün ve içerik görselleri ise Firebase Storage üzerinde depolanarak, uygulama içi hızlı erişim sağlanmıştır.</p><p>Patisca uygulamasında, kullanıcıların ürünleri renk ve beden seçeneklerine göre seçebilmesi için varyasyonlar oluşturulmuştur. Kullanıcılar, beğendikleri ürünleri sepete ekleyebilir ve güvenli bir şekilde sipariş oluşturabilirler. Kapıda ödeme seçeneği de uygulama içinde sunulmuştur.</p><p>Kullanıcıların uygulama içindeki içerikleri yönetebilmesi için React tabanlı bir yönetim paneli geliştirilmiştir. Bu panel, ürün, kategori ve banner yönetimini kapsamaktadır. Yönetim panelinin veri işlemlerinde TanStack Query kütüphanesi kullanılarak, verilerin sorgulanması ve güncellenmesi işlemleri hızlı ve etkili bir şekilde gerçekleştirilmiştir.</p><p>Patisca mobil uygulaması ile yönetim panelinin aynı veri altyapısı üzerinden bütünleşik çalışması sağlanmıştır. Bu sayede, kullanıcı deneyimi ve yönetim süreçleri arasında uyum oluşturulmuştur. Böylelikle, hem kullanıcılar hem de yöneticiler için sorunsuz bir deneyim sunulmuştur.</p>", "type": "text"}], "challengeBlocks": [{"id": "b33", "html": "<p>Patisca markası, tesettür giyim alanında bir mobil uygulama geliştirme ihtiyacı belirlemiştir. Kullanıcılar, çeşitli ürünleri kolay bir şekilde incelemek, sipariş vermek ve ürünleri kişisel tercihlerine göre seçmek istemektedir. Geleneksel perakende yöntemleri, müşterilere yeterli kolaylık sunmamaktadır. Bu nedenle, modern bir e-ticaret çözümüne ihtiyaç duyulmuştur.</p>", "type": "text"}], "galleryAssetIds": [], "coverImageAssetId": null}', '2026-09-09 10:16:30.638', 'cmts0wj9r0000tqzz9audivoc');
