INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtuib06t001dtq586ndr03ij', 'cmtr7cl6t0008tqqp09wci8d2', 1, '{"cta": {"url": null, "label": null}, "brand": {"name": "Metro Yazılım", "logoAssetId": "cmtuf0v7y00f7tqf330wia8hg"}, "footer": {"columns": [], "summary": "We help your business grow with database security, IT consulting and cloud infrastructure solutions."}, "vision": "To be the region''s preferred technology partner, a trusted IT company known for its innovative solutions.", "contact": {"email": "info@example.com", "phone": "+208-555-0112", "address": null}, "mission": "Enabling businesses to grow with secure, scalable and sustainable technology, producing value on every project through transparent communication and measurable results.", "termsBody": "<p>By using this site you accept the following terms of use. Content may be updated without prior notice.</p>", "navigation": [], "privacyBody": "<p>Your personal data is processed solely to provide our services and is never shared with third parties.</p>"}', '2026-09-09 19:43:49.685', 'cmts0wj9r0000tqzz9audivoc');
