INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtuie3w2002jtq58hnnxweir', 'cmtrwv4au0006tqdp24ckcxq8', 1, '{"text": "<p>Our experienced team supports your business growth with the right strategies and modern technologies.</p>", "banner": "About Us", "marquee": ["Cybersecurity", "IT Solutions", "Technology", "Data Security"], "features": [{"text": "We deliver fast, lasting solutions to complex challenges.", "title": "Problem Solving"}, {"text": "We use technology to shape the future today.", "title": "Mission & Vision"}], "seoTitle": null, "subtitle": "ABOUT US", "teamTitle": "Meet Our Dedicated Team", "authorName": "Muhammet Berat Arslan", "authorRole": "Co-Founder", "collageAlt": "Metro Yazılım specialists at work", "titleAfter": "to Increase Business Success", "titleAccent": "Technology", "titleBefore": "We Use", "teamSubtitle": "Team Members", "offeringTitle": "Lead the Way With Technology Trends", "experienceUnit": "Years", "offeringLabels": ["Website", "Android", "iOS", "Smartwatch", "IoT"], "seoDescription": null, "experienceLabel": "Experience", "experienceValue": "25", "offeringSubtitle": "What We Offer", "authorImageAssetId": "cmtue5sd00078tqf3us2itse2", "collageImageAssetId": "cmtudkusr0056tqf3mknm6e4d"}', '2026-09-09 19:46:14.45', 'cmts0wj9r0000tqzz9audivoc');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtudhbx70042tqf3vsb5kj7v', 'cmtpkwkq0002ftq54d9ou1g6y', 1, '{"blocks": [], "widget": {"limit": 4, "title": "", "layout": "grid", "source": "services", "bgImage": null, "columns": "4", "imageAlt": "", "kpiItems": [], "partType": "collection", "subtitle": "", "checklist": [], "logoItems": [{"altText": "Isra Holding", "assetId": "cmtuchyiu001mtqf3dcwmkg9m", "bgColor": ""}, {"altText": "World Press Federation", "assetId": "cmtucjx7c001qtqf33e2ysrv9", "bgColor": ""}, {"altText": "1TVTR", "assetId": "cmtucq7x1002ctqf3kvhke134", "bgColor": ""}, {"altText": "Melbourne Films", "assetId": "cmtucs10w002mtqf32gvjwllw", "bgColor": ""}, {"altText": "Istanbul Films", "assetId": "cmtud3bnf0038tqf3cw4gbvbh", "bgColor": ""}, {"altText": "Elit Istanbul Tıp Merkezi", "assetId": "cmtud3svh003itqf3gbecj4mc", "bgColor": ""}, {"altText": "Guzuco", "assetId": "cmtudh61q003ytqf3d5n04iga", "bgColor": ""}], "phoneHref": "", "statLabel": "", "statValue": "", "textAlign": "start", "categories": [], "kpiVariant": "counter-grid", "phoneLabel": "", "description": "", "heroVariant": "wave", "phoneNumber": "", "titleAccent": "", "itemCtaLabel": "", "marqueeItems": [], "processItems": [], "selectionMode": "latest", "bgImageAssetId": null, "primaryCtaHref": "", "primaryCtaLabel": "", "secondaryCtaHref": "", "testimonialItems": [], "secondaryCtaLabel": "", "selectedEntityIds": []}}', '2026-09-09 17:28:46.747', 'cmts0wj9r0000tqzz9audivoc');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtuic2gq0001tq2fbfro211z', 'cmtuiaf6f0041tqeda27lritz', 2, '{"slug": "crm-sistemi-nedir-ve-isletmelere-ne-kazandirir", "title": "What Is a CRM System and What Does It Bring to Businesses?", "author": "Berat", "blocks": [{"id": "b35", "html": "<p>Today, businesses use various methods to manage customer relationships. However, these methods often fall short. This is where the CRM system, or Customer Relationship Management, comes into play. CRM provides businesses with great convenience by storing customer information, communication history, sales processes, and more in a single center.</p>", "type": "text"}, {"id": "b36", "html": "<h3>What Is a CRM System?</h3><p>A CRM system is software that enables businesses to manage their customer relationships effectively. In addition to storing customer information, these systems also offer the ability to track communications through phone calls, emails, and messaging applications.</p>", "type": "text"}, {"id": "b37", "html": "<h3>Storing Customer Information</h3><p>When it comes to what customer information can be stored with CRM, this information spans a fairly wide range. Data such as customer name, contact details, purchase history, preferences, and communication history are all included in this system. All this information can be used to strengthen your customer relationships.</p>", "type": "text"}, {"id": "b38", "html": "<h3>Communication Tracking</h3><p>CRM systems quickly track phone calls, emails, and WhatsApp conversations. This makes the communication history with the customer easily accessible. As a result, sales teams can better understand customer needs and offer them suitable solutions.</p>", "type": "text"}, {"id": "b39", "html": "<h3>Distinguishing Between Prospective and Existing Customers</h3><p>CRM software enables businesses to develop tailored strategies by distinguishing between prospective and existing customers. Communication with prospective customers carries more importance at the beginning of the sales process. Existing customers, on the other hand, should be taken into consideration in activities aimed at earning their loyalty.</p>", "type": "text"}, {"id": "b40", "html": "<h3>Quote and Contract Tracking</h3><p>Processes such as quote, contract, payment, and invoice tracking are managed simply and effectively thanks to CRM systems. This way, it becomes clear at every stage of the sales process exactly what step things are at. This prevents wasted time and increases customer satisfaction.</p>", "type": "text"}, {"id": "b41", "html": "<h3>Managing the Sales Process</h3><p>Managing the sales process in stages is one of the biggest advantages of a CRM system. Information such as which tasks need to be done at each stage and when to contact which customer is stored in the system and made easily accessible. This allows teams to manage their work more efficiently.</p>", "type": "text"}, {"id": "b42", "html": "<h3>The Importance of Tasks and Reminders</h3><p>CRM systems prevent customer loss with their task and reminder creation feature. For example, when you need to contact a customer on a specific date, the system alerts you about it. This way, you never miss important opportunities.</p>", "type": "text"}, {"id": "b43", "html": "<h3>Differences Between Excel and CRM Usage</h3><p>Tracking customers with Excel provides limited data management. However, using a CRM offers a more organized and structured customer management system. Since CRM records communication history in addition to customer information, it allows businesses to perform better analysis.</p>", "type": "text"}, {"id": "b44", "html": "<h3>CRM Usage for Small Businesses</h3><p>Whether CRM usage is necessary for small businesses is frequently debated. However, managing customer relationships in an organized and effective way provides businesses with major advantages in the long run. CRM systems increase the growth potential of small businesses.</p>", "type": "text"}, {"id": "b45", "html": "<h3>What to Consider When Choosing the Right CRM</h3><p>Here are a few features to consider when choosing the right CRM software:</p><ul><li>User-friendly interface</li><li>Data security</li><li>Flexibility and customization options</li><li>Compatibility with different devices</li><li>Technical support services</li></ul>", "type": "text"}, {"id": "b46", "html": "<h3>Advantages of a Business-Specific CRM Software</h3><p>CRM software tailored to a business can be adapted to its needs and integrated into the business''s workflow. These types of solutions serve users in the way that best suits their needs and increase efficiency.</p><p>At Metro Yazılım, we develop CRM solutions tailored to your business. Strengthen your customer relationships with a CRM system suited to your needs.</p>", "type": "text"}], "excerpt": "Today, businesses use various methods to manage customer relationships. However, these methods often fall short.", "category": "Software", "seoTitle": "What Is a CRM System and Its Advantages for Businesses", "seoDescription": "A CRM system brings time and organization to businesses by simplifying customer tracking.", "coverImageAssetId": null}', '2026-09-09 19:44:39.29', 'cmtuhhwl40000tq4znuptne60');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtuic2hu000vtq2fvplp2kbr', 'cmtuic2hs000ttq2fjp6vdqy1', 2, '{"slug": "kurumsal-web-sitesi-yaptirirken-dikkat-edilmesi-gerekenler", "title": "Things to Consider When Building a Corporate Website", "author": "Berat", "blocks": [{"id": "b47", "html": "<p>Corporate websites are one of the most important parts of a business''s digital identity. A good website can make your brand look more professional and make it easier to reach potential customers. In this article, we will discuss the key factors that companies should pay attention to when having a corporate website built.</p>", "type": "text"}, {"id": "b48", "html": "<h3>The Importance of a Corporate Website</h3><p>A corporate website establishes your business''s online presence. Nowadays, people usually research products and services over the internet. Without a reliable website for your business, it becomes difficult to capture the attention of potential customers. In addition, your website also provides access to information about the products and services your company offers.</p>", "type": "text"}, {"id": "b49", "html": "<h3>The Necessity of Mobile-Friendly Design</h3><p>With the increasing use of mobile devices, it is essential that your website be mobile-friendly. Mobile-friendly design improves user experience and is favored by search engines. Search engines like Google prioritize mobile-friendly sites, so responsive design should be preferred.</p>", "type": "text"}, {"id": "b50", "html": "<h3>The Importance of Page Speed</h3><p>Fast loading of your website is a critical factor for user experience. Users can quickly abandon slow-loading pages. Additionally, page speed is also an influential factor for SEO, as search engines rank fast sites higher. Methods such as optimizing images and removing unnecessary plugins can be used to increase page speed.</p>", "type": "text"}, {"id": "b51", "html": "<h3>Design That Builds Trust</h3><p>Your website''s design should reflect your brand''s identity and inspire trust in visitors. Colors, fonts, and overall design harmony affect the trust potential customers place in your company. A professional design encourages users to spend more time on your site and increases conversion rates.</p>", "type": "text"}, {"id": "b52", "html": "<h3>Contact Information and Conversion Areas</h3><p>You should clearly share your contact information so that users can quickly get in touch with you. Conversion-focused elements such as a quote form, phone number, or email make it easier for potential customers to connect with you. These elements need to be prominently displayed.</p>", "type": "text"}, {"id": "b53", "html": "<h3>Why Is SEO Infrastructure Important?</h3><p>Properly setting up SEO infrastructure increases your website''s visibility in search engines. Effective use of keywords helps your site attract more visitors.</p>", "type": "text"}, {"id": "b54", "html": "<h3>What Is an Admin Panel?</h3><p>An admin panel allows you to easily update your website''s content. A user-friendly panel makes managing your content easier.</p>", "type": "text"}, {"id": "b55", "html": "<h3>What Security Measures Should Be in Place?</h3><p>An SSL certificate enhances the security of your website. Basic maintenance support is also important for protecting users'' data.</p>", "type": "text"}, {"id": "b56", "html": "<h3>References and About Us Page</h3><p>Correctly presenting your references and services on your website helps potential customers gain trust. The About Us page informs visitors by providing information about your company''s history and mission. These pages reflect your company''s professionalism.</p>", "type": "text"}, {"id": "b57", "html": "<h3>Conclusion</h3><p>In conclusion, a corporate website is not just a visual tool but also a platform that brings in customers. The factors to consider are vital to the success of your website. The combination of professional web design and the right strategies will make your brand stand out in the online world.</p><p>Contact Metro Yazılım to design your corporate website. Our expert team offers solutions tailored to your needs.</p>", "type": "text"}], "excerpt": "Corporate websites are one of the most important parts of a business''s digital identity. A good website can make your brand look more professional and make it easier to reach potential customers.", "category": "Web Design", "seoTitle": "Things to Consider When Building a Corporate Website", "seoDescription": "Information on the key factors that companies should consider when having a corporate website built.", "coverImageAssetId": null}', '2026-09-09 19:44:39.33', 'cmtuhhwl40000tq4znuptne60');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtuic2ik001ptq2fvmfoyus6', 'cmtuic2ii001ntq2fcub11out', 2, '{"slug": "ozel-yazilim-gelistirmenin-avantagesi", "title": "The Advantages and Necessity of Custom Software Development", "author": "Berat", "blocks": [{"id": "b58", "html": "<p>Custom software development is highly important for businesses looking to increase their efficiency and digitalize their processes. Custom software refers to software designed and developed specifically for the needs of a particular business. Unlike the general solutions offered by off-the-shelf software, these applications are created to meet the unique requirements of the business.</p>", "type": "text"}, {"id": "b59", "html": "<h3>Differences Between Off-the-Shelf Software and Custom Software</h3><p>Off-the-shelf software is developed for general use. Custom software, on the other hand, is designed to serve only a specific business. While off-the-shelf software can appeal to all industries, custom software focuses on the business''s specific processes. In short, the custom software development process offers solutions that are more suited to the business''s goals and processes.</p>", "type": "text"}, {"id": "b60", "html": "<h3>Businesses That Need Custom Software</h3><p>Businesses that need custom software are generally organizations operating in a specific industry, with complex business processes, or those that are growing. Such businesses cannot achieve sufficient efficiency with standard solutions and want to manage their processes more effectively by turning to custom software. For example, a manufacturing company may develop custom software to optimize its production processes.</p>", "type": "text"}, {"id": "b61", "html": "<h3>Advantages of Custom Software</h3><ul><li>Process Management: Custom software allows businesses to manage their processes better.</li><li>Efficiency: Custom solutions help employees perform their tasks faster and more effectively.</li><li>Reporting: It offers comprehensive reporting options for tracking business processes and performing performance analyses.</li></ul>", "type": "text"}, {"id": "b62", "html": "<h3>Use Cases</h3><p>Custom software development manifests itself in many areas. For example, a CRM system manages customer relationships, while ERP software integrates and manages resources within an organization. In addition, systems such as reservation systems, quotation and inventory management applications are also examples of custom software. These systems make businesses'' daily operations more efficient.</p>", "type": "text"}, {"id": "b63", "html": "<h3>Custom Software Development Process</h3><p>The custom software development process generally consists of several stages. First, a needs analysis is conducted. At this stage, the requirements of the business are determined. Then, during the design stage, the architecture of the software is created. During the development stage, coding is carried out. Finally, during the testing stage, the software''s shortcomings are addressed and it is delivered to the business.</p>", "type": "text"}, {"id": "b64", "html": "<h3>Cost, Timeline and Long-Term Benefit</h3><p>Although custom software development requires higher initial costs, it provides significant benefits in the long run. The initial investment cost is necessary to deliver a solution tailored to the business''s needs. A well-built custom software solution accelerates business processes over time and can reduce overall costs by increasing efficiency.</p>", "type": "text"}, {"id": "b65", "html": "<h3>How to Choose the Right Software Company?</h3><p>When choosing the right software company, the company''s experience, references and project history are important. In addition, customer support services and communication skills should also be taken into consideration.</p>", "type": "text"}, {"id": "b66", "html": "<h3>How Long Does the Custom Software Process Take?</h3><p>The custom software development process varies depending on the complexity of the project. Simple projects can be completed in a few months, while more complex solutions can take years.</p>", "type": "text"}, {"id": "b67", "html": "<h3>What Are the Advantages of Custom Software?</h3><p>Custom software increases efficiency and optimizes processes by offering solutions tailored to your business''s specific needs.</p>", "type": "text"}, {"id": "b68", "html": "<h3>Conclusion</h3><p>Custom software development helps businesses manage their business processes more effectively by offering tailored solutions. When enterprise software solutions are adapted to the needs of businesses, they provide great benefits in the long run.</p><p>Learn more about custom software solutions for your business with Metro Yazılım.</p>", "type": "text"}], "excerpt": "Custom software development is highly important for businesses looking to increase their efficiency and digitalize their processes. Custom software refers to software designed and developed specifically for the needs of a particular business.", "category": "Software", "seoTitle": "The Advantages of Custom Software Development", "seoDescription": "Digitalize your processes with custom software development, offering businesses solutions tailored to their needs.", "coverImageAssetId": null}', '2026-09-09 19:44:39.356', 'cmtuhhwl40000tq4znuptne60');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtuic2j7002jtq2ftlrcsrar', 'cmtuic2j6002htq2f8ws9xmqc', 2, '{"slug": "chatbot-entegresi-ile-sirket-verimliligi", "title": "Company Efficiency with Chatbot Integration", "author": "Berat", "blocks": [{"id": "b69", "html": "<p>In today''s business world, technological solutions are of great importance for ensuring customer satisfaction and increasing efficiency. At this point, chatbot integration offers businesses the opportunity to respond quickly and increase engagement. In our article, we will discuss how to integrate chatbots into websites, Telegram bot services, and the advantages Metro Yazılım offers in this field.</p>", "type": "text"}, {"id": "b70", "html": "<h3>Chatbot Integration for Websites</h3><p>Chatbots integrated into websites improve user experience by instantly responding to visitors'' questions. This makes it possible to interact with potential customers and quickly respond to their needs. Chatbots can always meet users'' requests by offering 24/7 service.</p>", "type": "text"}, {"id": "b71", "html": "<h3>Benefits of Chatbots</h3><ul><li>Increases customer satisfaction with fast response times.</li><li>Reduces workload, enabling employees to work more efficiently.</li><li>Reaches a wide audience with the ability to be used on different platforms.</li><li>Strengthens marketing strategies with data collection and analysis capabilities.</li></ul>", "type": "text"}, {"id": "b72", "html": "<h3>Telegram Bot Service</h3><p>Telegram is a platform where users can exchange instant messages and information. Metro Yazılım offers businesses the chance to increase user engagement with its Telegram bot service. These bots enable users to quickly obtain information and request support via Telegram.</p>", "type": "text"}, {"id": "b73", "html": "<h3>Advantages of Telegram Bots</h3><ul><li>Provides ease of use with a user-friendly interface.</li><li>Informs users with instant notifications.</li><li>Quickly answers users'' questions with automatic response systems.</li></ul>", "type": "text"}, {"id": "b74", "html": "<h3>Metro Yazılım''s Chatbot Service</h3><p>Metro Yazılım can offer chatbot services not only on its own website but also on different platforms. It aims to increase businesses'' customer engagement with customized solutions tailored to user needs. This way, companies can quickly access the information they need.</p>", "type": "text"}, {"id": "b75", "html": "<h3>Benefits of Chatbot Development for Users</h3><p>Chatbots offer many advantages for users. First, they provide instant access to information. Users can easily access the information they need regardless of time differences. In addition, interactions with chatbots enrich the user experience and increase satisfaction.</p>", "type": "text"}, {"id": "b76", "html": "<h3>What kind of questions can chatbots answer?</h3><p>Chatbots can instantly answer frequently asked questions, product information, and service details. They can also be used to direct users'' requests.</p>", "type": "text"}, {"id": "b77", "html": "<h3>What is the chatbot integration process like?</h3><p>Chatbot integration usually consists of several stages: needs analysis, design, development, and testing. Metro Yazılım manages these processes quickly and effectively.</p>", "type": "text"}, {"id": "b78", "html": "<h3>How does a Telegram bot work?</h3><p>Telegram bots listen to users'' commands and automatically provide the necessary responses. Users can interact with the bot through specific commands.</p>", "type": "text"}, {"id": "b79", "html": "<h3>Conclusion</h3><p>Chatbot integration and Telegram bot service are effective methods for companies to increase customer engagement and ensure efficiency. With its experience in this field, Metro Yazılım provides businesses with customized solutions, giving them a competitive advantage.</p><p>Contact us to learn more about chatbot solutions with Metro Yazılım.</p>", "type": "text"}], "excerpt": "In today''s business world, technological solutions are of great importance for ensuring customer satisfaction and increasing efficiency. At this point, chatbot integration offers businesses the opportunity to respond quickly and increase engagement.", "category": "Technology", "seoTitle": "Increasing Efficiency with Chatbot Integration", "seoDescription": "Increase your company''s customer engagement with chatbot integration. Follow the path with Metro Yazılım regarding WhatsApp and Telegram bots. Gain customers.", "coverImageAssetId": null}', '2026-09-09 19:44:39.38', 'cmtuhhwl40000tq4znuptne60');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtuic2jw003dtq2fyt2ngdhb', 'cmtuic2jv003btq2fhw06uaas', 2, '{"slug": "voltstep-sports-cok-modullu-e-ticaret-platformu", "title": "VoltStep Sports: Multi-Module E-Commerce Platform", "client": null, "category": "E-Commerce", "seoTitle": "VoltStep Sports: E-Commerce Platform Development", "seoDescription": "VoltStep Sports offers a secure online shopping experience with its multi-module e-commerce platform. Built with custom e-commerce software.", "solutionBlocks": [{"id": "b32", "html": "<p>VoltStep Sports was designed as a comprehensive e-commerce platform. A system was built that unifies critical processes such as product, variant, and stock management within a single infrastructure. This system meets user needs by offering dynamically manageable product attributes and a comprehensive data structure.</p><p>VoltStep Sports was developed as a mobile-friendly customer storefront using React 19 and Tailwind CSS. This allows users to access the platform comfortably from any device. Virtualized listing technology was used to ensure performance with large product lists, minimizing page load times.</p><p>The project is supported by a scalable, centralized backend architecture based on NestJS. Using PostgreSQL and Prisma, a comprehensive data structure with more than 40 models was created. An EAV-based attribute system was developed for dynamic product management. As a result, an infrastructure for color-based variants, stock, pricing, and image definitions was integrated into the products.</p><p>The admin panel was developed using React 19, Vite, and TanStack Query. Users can easily manage product and category administration, as well as campaign and pricing processes. In addition, drag-and-drop features enable category, brand, collection, and tag management. Critical operations are logged with AuditLog, enhancing security.</p><p>The cart and order creation flows were carefully developed to make the shopping experience easier for users. A secure online payment infrastructure was established with PayTR integration. In addition, a rating and review system for purchased products allows the collection of user feedback. Post-order return and exchange processes were also incorporated into the system to provide flexibility.</p><p>A dedicated support ticket system was created to track customer requests. This system offers a platform where users can quickly submit their questions and issues. In addition, thanks to an i18next-based localization system for multi-language support, service is provided in different languages.</p><p>A notification infrastructure was developed for both users and staff. Thanks to this system, important updates and notifications are delivered instantly. Users are informed about order statuses, while staff can receive alerts for critical tasks.</p><p>In the project, a webhook infrastructure was prepared to allow external systems to connect. API documentation for the backend services was created with Swagger, making it easier for developers to access the API. In addition, order documents are generated automatically with a PDF generation system.</p><p>As a result, VoltStep Sports was delivered as a user-friendly and comprehensive e-commerce platform that brings together various modules. All processes, from the customer storefront to the admin panel, and from the backend API to the data structure, were developed as an integrated whole, resulting in a system that meets all requirements.</p>", "type": "text"}], "challengeBlocks": [{"id": "b31", "html": "<p>Due to the limited features of the existing e-commerce system, the client aimed to increase efficiency and improve the user experience. Product, variant, stock, campaign, and payment processes needed to be managed within an integrated structure. Establishing a robust system that would allow users to easily carry out post-purchase return and exchange processes was also identified as an important need.</p>", "type": "text"}], "galleryAssetIds": [], "coverImageAssetId": null}', '2026-09-09 19:44:39.405', 'cmtuhhwl40000tq4znuptne60');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtuic2kk0047tq2fg8iu41oz', 'cmtuic2kj0045tq2fvrg1q85o', 2, '{"slug": "patisca-mobil-e-ticaret-uygulamasi", "title": "Patisca Mobile E-Commerce Application", "client": "Patisca", "category": "Mobile Application", "seoTitle": "Patisca Mobile E-Commerce Application", "seoDescription": "Metro Yazılım developed a mobile e-commerce application for the Patisca brand on iOS and Android platforms. It offers solutions for the modest fashion sector.", "solutionBlocks": [{"id": "b34", "html": "<p>Metro Yazılım developed a mobile e-commerce application tailored to users'' needs for the Patisca project. The application was designed with a focus on user experience, allowing products to be comfortably selected along with their color and size variations. In addition, a structure was established to facilitate the processes of adding products to the cart and creating orders.</p><p>The Patisca mobile application was developed using Flutter and Dart. Flutter, a high-performance framework, makes it easier to develop applications for both iOS and Android platforms. The GetX library was used for the application''s state management, effectively managing the application''s state.</p><p>Firebase Authentication was used to allow users to easily register and log in to the application. This technology provides a secure user experience and performs authentication processes quickly.</p><p>Cloud Firestore was used for product, category, banner, user, and order data. This database provides real-time data synchronization while also improving the application''s performance. Product and content images were stored on Firebase Storage, providing fast in-app access.</p><p>In the Patisca application, variations were created to allow users to select products based on color and size options. Users can add products they like to their cart and place orders securely. A cash-on-delivery option was also offered within the application.</p><p>A React-based admin panel was developed to allow users to manage content within the application. This panel covers product, category, and banner management. Using the TanStack Query library for the admin panel''s data operations, querying and updating data was carried out quickly and effectively.</p><p>The Patisca mobile application and the admin panel were designed to work in an integrated manner on the same data infrastructure. This ensured harmony between the user experience and management processes. Thus, a seamless experience was provided for both users and administrators.</p>", "type": "text"}], "challengeBlocks": [{"id": "b33", "html": "<p>The Patisca brand identified a need to develop a mobile application in the modest fashion sector. Users wanted to easily browse various products, place orders, and select products according to their personal preferences. Traditional retail methods did not offer customers sufficient convenience. Therefore, a modern e-commerce solution was needed.</p>", "type": "text"}], "galleryAssetIds": [], "coverImageAssetId": null}', '2026-09-09 19:44:39.429', 'cmtuhhwl40000tq4znuptne60');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtuic2l5004ztq2f4gn3gzo6', 'cmtuh2epo000ftq58op9smyex', 2, '{"icon": null, "slug": "ozel-yazilim-gelistirme-hizmetleri", "title": "Custom Software Development Services", "blocks": [{"id": "b1", "html": "<p>Custom software development is the process of providing software solutions tailored to the needs and workflows of businesses. While off-the-shelf software typically addresses standard business processes, custom software projects are designed to meet the unique requirements of a business. This service is preferred by businesses aiming to increase efficiency, optimize processes, and gain a competitive advantage.</p><p>At the end of the project, we provide our clients with comprehensive system documentation, source code, and the necessary management access. This is critical for you to better understand the software and make changes when needed. In addition, with technical support provided at every stage of the project, we take the necessary steps to ensure the software remains durable and sustainable in the long term.</p><p></p><h3>Who it''s suitable for</h3><ul><li><p>Businesses for which off-the-shelf software falls short</p></li><li><p>Entrepreneurs and startups</p></li><li><p>SMEs</p></li><li><p>Corporate companies</p></li><li><p>Industries with special processes</p></li></ul><p></p><h3>What it covers</h3><ul><li><p>Management panels</p></li><li><p>CRM systems</p></li><li><p>Business tracking applications</p></li><li><p>Reservation systems</p></li><li><p>Accounting and operations software</p></li><li><p>API integrations</p></li><li><p>Web and mobile-based custom projects</p></li></ul><p></p><h3>How we work</h3><ul><li><p>Needs Analysis: We analyze your business''s needs and existing workflows.</p></li><li><p>Project Definition: We define the project scope, user roles, and core features.</p></li><li><p>Design Process: We design a user-friendly interface and management panel.</p></li><li><p>Backend Development: We develop a secure and scalable backend infrastructure.</p></li><li><p>Integration: We integrate the necessary third-party services and API systems.</p></li><li><p>Compatible Development: We develop the software to be compatible with desktop, tablet, and mobile devices.</p></li><li><p>Testing and Security: We carry out testing, security, and performance checks.</p></li><li><p>Deployment Process: We handle the deployment of the software to the server and go-live processes.</p></li><li><p>Support and Maintenance: We provide maintenance, development, and technical support after project delivery.</p></li><li><p>Documentation: The client is delivered the source code, system documentation, and management access.</p></li></ul><p></p><h3>Technologies we use</h3><ul><li><p>Next.js: Used to develop fast and user-friendly web applications.</p></li><li><p>React: A powerful library for interface development.</p></li><li><p>Node.js: Creates efficient applications by running JavaScript on the server side.</p></li><li><p>NestJS: Used to develop modern and scalable server applications.</p></li><li><p>TypeScript: A strongly typed version of JavaScript that helps prevent errors in large projects.</p></li><li><p>PostgreSQL: A powerful open-source database that enhances data security.</p></li><li><p>MongoDB: A NoSQL database offering flexible data structures.</p></li><li><p>Redis: An in-memory database providing fast data access.</p></li><li><p>Docker: Simplifies the portability and management of applications.</p></li><li><p>Cloud Services: Provides scalable and accessible infrastructure.</p></li></ul><p></p>", "type": "text"}], "summary": "We develop secure, scalable, and sustainable software solutions tailored to your business''s needs and goals.", "seoTitle": "Custom Software Development Services", "imageAssetId": null, "seoDescription": "Metro Yazılım delivers custom software solutions tailored to your business needs. Build secure, scalable, and manageable software."}', '2026-09-09 19:44:39.45', 'cmtuhhwl40000tq4znuptne60');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtudhe8c0048tqf34r8ivne0', 'cmtpkwkq0002ftq54d9ou1g6y', 1, '{"blocks": [], "widget": {"limit": 4, "title": "", "layout": "grid", "source": "services", "bgImage": null, "columns": "4", "imageAlt": "", "kpiItems": [], "partType": "collection", "subtitle": "", "checklist": [], "logoItems": [{"altText": "Isra Holding", "assetId": "cmtuchyiu001mtqf3dcwmkg9m", "bgColor": ""}, {"altText": "World Press Federation", "assetId": "cmtucjx7c001qtqf33e2ysrv9", "bgColor": ""}, {"altText": "1TVTR", "assetId": "cmtucq7x1002ctqf3kvhke134", "bgColor": ""}, {"altText": "Melbourne Films", "assetId": "cmtucs10w002mtqf32gvjwllw", "bgColor": ""}, {"altText": "Istanbul Films", "assetId": "cmtud3bnf0038tqf3cw4gbvbh", "bgColor": ""}, {"altText": "Elit Istanbul Tıp Merkezi", "assetId": "cmtud3svh003itqf3gbecj4mc", "bgColor": ""}, {"altText": "Guzuco", "assetId": "cmtudh61q003ytqf3d5n04iga", "bgColor": ""}], "phoneHref": "", "statLabel": "", "statValue": "", "textAlign": "start", "categories": [], "kpiVariant": "counter-grid", "phoneLabel": "", "description": "", "heroVariant": "wave", "phoneNumber": "", "titleAccent": "", "itemCtaLabel": "", "marqueeItems": [], "processItems": [], "selectionMode": "latest", "bgImageAssetId": null, "primaryCtaHref": "", "primaryCtaLabel": "", "secondaryCtaHref": "", "testimonialItems": [], "secondaryCtaLabel": "", "selectedEntityIds": []}}', '2026-09-09 17:28:49.74', 'cmts0wj9r0000tqzz9audivoc');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtudjbkl0050tqf3rakiu6l0', 'cmtpkwkq0002ftq54d9ou1g6y', 1, '{"blocks": [], "widget": {"limit": 4, "title": "", "layout": "grid", "source": "services", "bgImage": null, "columns": "4", "imageAlt": "", "kpiItems": [], "partType": "collection", "subtitle": "", "checklist": [], "logoItems": [{"altText": "Isra Holding", "assetId": "cmtuchyiu001mtqf3dcwmkg9m", "bgColor": ""}, {"altText": "World Press Federation", "assetId": "cmtucjx7c001qtqf33e2ysrv9", "bgColor": ""}, {"altText": "1TVTR", "assetId": "cmtucq7x1002ctqf3kvhke134", "bgColor": ""}, {"altText": "Melbourne Films", "assetId": "cmtucs10w002mtqf32gvjwllw", "bgColor": "#000000"}, {"altText": "Istanbul Films", "assetId": "cmtud3bnf0038tqf3cw4gbvbh", "bgColor": "#000000"}, {"altText": "Elit Istanbul Tıp Merkezi", "assetId": "cmtud3svh003itqf3gbecj4mc", "bgColor": ""}, {"altText": "Guzuco", "assetId": "cmtudh61q003ytqf3d5n04iga", "bgColor": "#000000"}, {"altText": "Medipol", "assetId": "cmtudhpd8004etqf3ykpvgin7", "bgColor": ""}], "phoneHref": "", "statLabel": "", "statValue": "", "textAlign": "start", "categories": [], "kpiVariant": "counter-grid", "phoneLabel": "", "description": "", "heroVariant": "wave", "phoneNumber": "", "titleAccent": "", "itemCtaLabel": "", "marqueeItems": [], "processItems": [], "selectionMode": "latest", "bgImageAssetId": null, "primaryCtaHref": "", "primaryCtaLabel": "", "secondaryCtaHref": "", "testimonialItems": [], "secondaryCtaLabel": "", "selectedEntityIds": []}}', '2026-09-09 17:30:19.606', 'cmts0wj9r0000tqzz9audivoc');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtuic2ls005ttq2f5ldxb23f', 'cmtuic2lr005rtq2fnl8ej45v', 2, '{"icon": null, "slug": "web-uygulama-gelistirme", "title": "Web Application Development", "blocks": [{"id": "b6", "html": "<p>Web application development is an essential service that helps businesses manage their business processes over the internet. A well-designed web application offers solutions customized to users'' needs, increasing business efficiency. These browser-based applications provide a fast, secure, and mobile-friendly experience.</p><p>Once the project is completed, a web application, an admin panel, and all necessary integrations that meet users'' needs become ready. Users can access system data, make content updates, and reach performance reports.</p>", "type": "text"}, {"id": "b7", "html": "<h3>Who is it suitable for</h3><ul><li>Businesses that want to manage business processes over the internet</li><li>Entrepreneurs developing startups and new projects</li><li>E-commerce companies and online sales platforms</li><li>Corporate companies and managers</li></ul>", "type": "text"}, {"id": "b8", "html": "<h3>What it covers</h3><ul><li>Corporate admin panels</li><li>Customer portals</li><li>Reservation systems</li><li>CRM applications</li><li>SaaS projects</li><li>Reporting dashboards</li><li>Dealer systems and custom web platforms</li></ul>", "type": "text"}, {"id": "b9", "html": "<h3>How we work</h3><ul><li>Needs Analysis: We determine the project''s users, roles, and core use cases.</li><li>Interface Design: We design interfaces compatible with mobile, tablet, and desktop devices.</li><li>Development: We develop pages that load quickly and are readable by search engines.</li><li>Authorization Systems: We build user, authorization, and role-based access systems.</li><li>API and Database: We develop secure API and database infrastructure.</li><li>Integrations: We implement payment, shipping, email, SMS, and external service integrations.</li><li>Admin Panel: We ensure content and system data can be controlled from the admin panel.</li><li>Testing Processes: We perform performance, security, and user experience tests.</li><li>Launch: We deploy the web application to the server and complete domain connections.</li><li>Maintenance and Support: We support the project''s maintenance, updates, and new feature development processes.</li></ul>", "type": "text"}, {"id": "b10", "html": "<h3>Technologies we use</h3><ul><li>Next.js: Used for server-side rendering and static site generation.</li><li>React: A library used for developing user interfaces.</li><li>TypeScript: Makes JavaScript type-safe.</li><li>Node.js: Used to run JavaScript on the server side.</li><li>NestJS: A structured framework for server applications.</li><li>PostgreSQL: A powerful database management system.</li><li>MongoDB: Used for NoSQL databases.</li><li>Redis: An in-memory data structure for fast data access.</li><li>REST API: Enables communication between systems.</li><li>Docker: Enables applications to run in virtual environments.</li><li>Cloudflare: Used to speed up and enhance the security of web applications.</li></ul>", "type": "text"}], "summary": "We develop fast, secure, user-friendly, and scalable web applications that let you easily manage your business processes in a digital environment.", "seoTitle": "Web Application Development", "imageAssetId": null, "seoDescription": "Accelerate your business processes with professional web application development services from Metro Yazılım. We provide fast and secure solutions."}', '2026-09-09 19:44:39.472', 'cmtuhhwl40000tq4znuptne60');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtuic2md006ntq2fbkau90yo', 'cmtuic2mb006ltq2fvg0ojcea', 2, '{"icon": null, "slug": "mobil-uygulama-gelistirme-hizmetleri", "title": "Mobile Application Development Services", "blocks": [{"id": "b11", "html": "<p>Mobile application development is a process that enables businesses and entrepreneurs to bring their products or services to mobile devices. Today, the importance of mobile applications is steadily growing, offering solutions that improve user experience and increase engagement. At Metro Yazılım, we design and develop user-focused, fast, and secure mobile applications.</p><p>At the end of the mobile application development process, we deliver a user-friendly, fast, and secure mobile application. We also simplify user and content management processes with an integrated management panel. Your application is delivered ready to be published on both the App Store and Google Play.</p>", "type": "text"}, {"id": "b12", "html": "<h3>Who it''s suitable for</h3><ul><li>Businesses wanting to bring their products or services to mobile devices</li><li>Startups and entrepreneurs</li><li>E-commerce companies</li><li>Service providers</li><li>Corporate companies seeking mobile solutions for their employees</li></ul>", "type": "text"}, {"id": "b13", "html": "<h3>What it covers</h3><ul><li>E-commerce applications</li><li>Reservation applications</li><li>Corporate applications</li><li>Customer applications</li><li>Mobile systems for field teams</li><li>Membership and subscription applications</li></ul>", "type": "text"}, {"id": "b14", "html": "<h3>How we work</h3><ul><li>We analyze the mobile application idea and target user audience.</li><li>We determine the core features and user flows of the application.</li><li>We develop solutions with a shared codebase for iOS and Android.</li><li>We design modern and user-friendly mobile interfaces.</li><li>We build user registration, login, and authorization systems.</li><li>We integrate notification, location, camera, payment, and file upload features.</li><li>We develop a web-based management panel to manage the mobile application.</li><li>We prepare the backend API and database infrastructure.</li><li>We test the application on different screen sizes and devices.</li><li>We perform performance, data security, and error checks.</li><li>We provide support during App Store and Google Play publishing processes.</li><li>After launch, we provide maintenance, updates, and new feature development services.</li></ul>", "type": "text"}, {"id": "b15", "html": "<h3>Technologies we use</h3><ul><li>Flutter: A fast and effective application development tool for both iOS and Android.</li><li>React Native: A framework used for cross-platform application development.</li><li>Firebase: Provides real-time database and user authentication services.</li><li>Node.js: Used to develop fast and scalable applications on the server side.</li><li>NestJS: A powerful server application framework.</li><li>TypeScript: A superset of JavaScript that makes application development safer.</li><li>PostgreSQL: A powerful and reliable relational database management system.</li><li>REST API: A standard method for exchanging data between applications.</li><li>Cloud services: Offer flexible solutions for hosting and scaling your applications.</li></ul>", "type": "text"}], "summary": "We develop high-performance, secure, and user-focused mobile applications for iOS and Android devices. We manage the entire process from the idea stage to store publishing and maintenance.", "seoTitle": "Mobile Application Development", "imageAssetId": null, "seoDescription": "Metro Yazılım offers modern mobile application development services for iOS and Android. Bring your business to the mobile platform."}', '2026-09-09 19:44:39.493', 'cmtuhhwl40000tq4znuptne60');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtuic2mz007htq2fmqfooqkv', 'cmtuic2mx007ftq2ftektxpow', 2, '{"icon": null, "slug": "e-ticaret-yazilimi-gelistirme-hizmeti", "title": "E-commerce Software Development Service", "blocks": [{"id": "b16", "html": "<p>Our e-commerce software development service is specially designed for brands, stores, manufacturers, wholesalers and growing e-commerce businesses that want to sell products online. With this service, we aim to increase efficiency by integrating your business''s product, stock, order, payment, shipping and customer processes under a single system.</p><p>At the end of the project, our clients gain an infrastructure with a custom e-commerce software and management panel that allows them to seamlessly manage product, stock, order, payment and shipping processes. In addition, they can track their business performance with comprehensive reporting and analysis tools.</p>", "type": "text"}, {"id": "b17", "html": "<h3>Who it''s suitable for</h3><ul><li>Brands wanting to sell products online</li><li>Stores and retailers</li><li>Manufacturers and wholesalers</li><li>Growing e-commerce businesses</li></ul>", "type": "text"}, {"id": "b18", "html": "<h3>What it covers</h3><ul><li>Custom e-commerce website development</li><li>Mobile e-commerce app creation</li><li>Systems integrated with the management panel</li><li>Product and variation management</li><li>Campaign and discount management</li><li>Payment and shipping integration</li><li>Reporting and analysis screens</li></ul>", "type": "text"}, {"id": "b19", "html": "<h3>How we work</h3><ul><li>Needs Analysis: We examine your business''s product structure and sales model in detail.</li><li>Infrastructure Setup: We build product, category, brand, collection and variation systems.</li><li>Management-Oriented Design: We develop stock, pricing, discount, coupon and campaign management.</li><li>Interface Design: We design a mobile-friendly and fast-performing e-commerce interface.</li><li>Functional Features: We prepare cart, favorites, membership and order tracking features.</li><li>Payment Integration: We integrate İyzico, PayTR and suitable payment systems.</li><li>Shipping Integration: We provide integration with shipping companies and delivery options.</li><li>Customer Management: We connect order, customer, return and support processes to the management panel.</li><li>Multilingual Support: We set up an infrastructure supporting Turkish, English and other language options.</li><li>SEO and Analysis: We develop technical SEO, product schemas and search-engine-friendly pages.</li><li>Measurement and Security: We integrate GA4, conversion tracking and ad measurement systems.</li><li>Support and Launch: We provide server setup, deployment and technical support for the project.</li></ul>", "type": "text"}, {"id": "b20", "html": "<h3>Technologies we use</h3><ul><li>Next.js</li><li>React</li><li>Node.js</li><li>NestJS</li><li>PostgreSQL</li><li>Redis</li><li>Cloudflare</li><li>İyzico and PayTR</li></ul>", "type": "text"}], "summary": "We boost your sales with modern e-commerce solutions that strengthen your brand''s digital journey and simplify the shopping, payment and customer experience.", "seoTitle": "E-commerce Software Development", "imageAssetId": null, "seoDescription": "Metro Yazılım enables you to manage your business processes on a single platform with custom e-commerce software solutions. Develop fast and reliable systems."}', '2026-09-09 19:44:39.515', 'cmtuhhwl40000tq4znuptne60');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtudi9oe004otqf36hcpvpwf', 'cmtpkwkq0002ftq54d9ou1g6y', 1, '{"blocks": [], "widget": {"limit": 4, "title": "", "layout": "grid", "source": "services", "bgImage": null, "columns": "4", "imageAlt": "", "kpiItems": [], "partType": "collection", "subtitle": "", "checklist": [], "logoItems": [{"altText": "Isra Holding", "assetId": "cmtuchyiu001mtqf3dcwmkg9m", "bgColor": ""}, {"altText": "World Press Federation", "assetId": "cmtucjx7c001qtqf33e2ysrv9", "bgColor": ""}, {"altText": "1TVTR", "assetId": "cmtucq7x1002ctqf3kvhke134", "bgColor": ""}, {"altText": "Melbourne Films", "assetId": "cmtucs10w002mtqf32gvjwllw", "bgColor": "#d6d6d6"}, {"altText": "Istanbul Films", "assetId": "cmtud3bnf0038tqf3cw4gbvbh", "bgColor": "#d6d6d6"}, {"altText": "Elit Istanbul Tıp Merkezi", "assetId": "cmtud3svh003itqf3gbecj4mc", "bgColor": ""}, {"altText": "Guzuco", "assetId": "cmtudh61q003ytqf3d5n04iga", "bgColor": "#d6d6d6"}, {"altText": "Medipol", "assetId": "cmtudhpd8004etqf3ykpvgin7", "bgColor": ""}], "phoneHref": "", "statLabel": "", "statValue": "", "textAlign": "start", "categories": [], "kpiVariant": "counter-grid", "phoneLabel": "", "description": "", "heroVariant": "wave", "phoneNumber": "", "titleAccent": "", "itemCtaLabel": "", "marqueeItems": [], "processItems": [], "selectionMode": "latest", "bgImageAssetId": null, "primaryCtaHref": "", "primaryCtaLabel": "", "secondaryCtaHref": "", "testimonialItems": [], "secondaryCtaLabel": "", "selectedEntityIds": []}}', '2026-09-09 17:29:30.494', 'cmts0wj9r0000tqzz9audivoc');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtuic2nk008btq2fc78em07l', 'cmtuic2nj0089tq2fe61wyedc', 2, '{"icon": null, "slug": "yapay-zeka-ve-is-sureci-otomasyonlari", "title": "AI and Business Process Automations", "blocks": [{"id": "b21", "html": "<p>AI and business process automations are designed to increase business efficiency and prevent time loss. By automating repetitive and time-consuming operations, they enable businesses to manage their operations more effectively. Thanks to this service, customer service becomes faster and business processes become more controllable.</p><p>When we complete our services, you obtain automation systems designed specifically for your business needs. With these systems, you can respond to customer requests faster, increasing customer satisfaction, manage your business processes more efficiently, and save time.</p>", "type": "text"}, {"id": "b22", "html": "<h3>Who it''s suitable for</h3><ul><li>Businesses that want to speed up customer support processes</li><li>Companies that want to reduce repetitive operations</li><li>Corporate structures seeking efficiency</li><li>All industries that want to optimize their processes with AI</li></ul>", "type": "text"}, {"id": "b23", "html": "<h3>What it covers</h3><ul><li>Website chatbot development</li><li>Automation of customer support assistants</li><li>Content production systems</li><li>Quote preparation automation</li><li>Email automation</li><li>Data processing and reporting solutions</li><li>CRM integration</li><li>Building workflows via n8n</li></ul>", "type": "text"}, {"id": "b24", "html": "<h3>How we work</h3><ul><li>We identify repetitive and time-consuming processes within the business.</li><li>We determine the business steps and data sources suitable for automation.</li><li>We develop an AI-powered chatbot customized for the website.</li><li>We customize the chatbot with the business''s services, products, and documents.</li><li>We build systems that answer customer questions and collect requests.</li><li>We automate email, form, CRM, and management panel processes.</li><li>We set up multi-step automation workflows via n8n.</li><li>We provide content, quote, summary, and report generation with AI.</li><li>We offer integration options with Telegram, WhatsApp, websites, and various platforms.</li><li>We ensure that transactions are logged and tracked from the management panel.</li><li>We create a controlled working system for processes requiring human approval.</li><li>We take data security, authorization, and usage costs into account.</li><li>We provide maintenance and development support for automations after setup.</li></ul>", "type": "text"}, {"id": "b25", "html": "<h3>Technologies we use</h3><ul><li>OpenAI API</li><li>AI Models</li><li>n8n</li><li>Node.js</li><li>REST API</li><li>Webhook</li><li>PostgreSQL</li><li>Redis</li><li>Custom Integrations</li></ul>", "type": "text"}], "summary": "With AI and automation technologies, we reduce repetitive tasks, accelerate your operational processes, and help you manage your business more efficiently.", "seoTitle": "AI and Business Process Automations", "imageAssetId": null, "seoDescription": "Optimize your business processes with AI and automation solutions. Discover ways to increase efficiency."}', '2026-09-09 19:44:39.536', 'cmtuhhwl40000tq4znuptne60');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtuic2o20095tq2focwea010', 'cmtuic2o10093tq2f0eevelxz', 2, '{"icon": null, "slug": "yazilim-bakim-ve-teknik-destek-hizmeti", "title": "Software Maintenance and Technical Support Service", "blocks": [{"id": "b26", "html": "<p>Our software maintenance and technical support service is provided to ensure that your existing website, mobile application, or custom software systems operate reliably and efficiently. This service addresses various needs such as reviewing the technical infrastructure of software, performing updates, and resolving issues that may arise.</p><p>As a result of our software maintenance and technical support service, you obtain an updated, secure, and performance-enhanced software system. In addition, you stay informed about the status of your system through regular reports.</p>", "type": "text"}, {"id": "b27", "html": "<h3>Who it''s suitable for</h3><ul><li>Businesses with an existing website</li><li>Companies developing mobile applications</li><li>E-commerce systems conducting online sales</li><li>Companies using custom software solutions</li></ul>", "type": "text"}, {"id": "b28", "html": "<h3>What it covers</h3><ul><li>Bug fixing and troubleshooting</li><li>Performance improvement</li><li>Security updates</li><li>Server management and configuration</li><li>Backup and restoration processes</li><li>New feature development</li><li>Integration maintenance and support</li><li>Technical consultancy services</li></ul>", "type": "text"}, {"id": "b29", "html": "<h3>How we work</h3><ul><li>Analysis of the existing system: We examine the software''s code structure and server infrastructure.</li><li>Reporting of bugs and security issues: We report detected issues in detail.</li><li>Security and performance improvements: We fix non-functioning or faulty features and increase page load speed.</li><li>Performing updates: We update software packages and the technologies used in a controlled manner.</li><li>Database checks: We check database performance and data integrity.</li><li>Server configuration: We check server, Docker, Nginx, SSL, and domain settings.</li><li>Adjusting security settings: We optimize Cloudflare, CDN, and caching settings.</li><li>Planning backup processes: We establish backup and, if needed, restoration processes.</li><li>Checking integrations: We ensure that payment, shipping, and other integrations work properly.</li><li>Adding new features: We add new features and management screens to the existing system.</li><li>Reporting: We record all operations and provide the client with a detailed report.</li><li>Maintenance service model: We offer flexible solutions through a monthly support or project-based working model.</li></ul>", "type": "text"}, {"id": "b30", "html": "<h3>Technologies we use</h3><ul><li>Next.js</li><li>React</li><li>Node.js</li><li>NestJS</li><li>Flutter</li><li>PostgreSQL</li><li>MongoDB</li><li>Docker</li><li>Nginx</li><li>Cloudflare</li></ul>", "type": "text"}], "summary": "We provide maintenance and technical support services to ensure your software systems operate securely, up to date, and without interruption. We keep your system continuously active through performance improvements, security updates, and bug fixes.", "seoTitle": "Software Maintenance and Technical Support", "imageAssetId": null, "seoDescription": "Enhance the security and performance of your systems with our software maintenance service. We provide bug fixing, updates, and technical support."}', '2026-09-09 19:44:39.555', 'cmtuhhwl40000tq4znuptne60');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtudiso4004utqf3626c2v5x', 'cmtpkwkq0002ftq54d9ou1g6y', 1, '{"blocks": [], "widget": {"limit": 4, "title": "", "layout": "grid", "source": "services", "bgImage": null, "columns": "4", "imageAlt": "", "kpiItems": [], "partType": "collection", "subtitle": "", "checklist": [], "logoItems": [{"altText": "Isra Holding", "assetId": "cmtuchyiu001mtqf3dcwmkg9m", "bgColor": "#0a2540"}, {"altText": "World Press Federation", "assetId": "cmtucjx7c001qtqf33e2ysrv9", "bgColor": ""}, {"altText": "1TVTR", "assetId": "cmtucq7x1002ctqf3kvhke134", "bgColor": ""}, {"altText": "Melbourne Films", "assetId": "cmtucs10w002mtqf32gvjwllw", "bgColor": "#d6d6d6"}, {"altText": "Istanbul Films", "assetId": "cmtud3bnf0038tqf3cw4gbvbh", "bgColor": "#d6d6d6"}, {"altText": "Elit Istanbul Tıp Merkezi", "assetId": "cmtud3svh003itqf3gbecj4mc", "bgColor": ""}, {"altText": "Guzuco", "assetId": "cmtudh61q003ytqf3d5n04iga", "bgColor": "#d6d6d6"}, {"altText": "Medipol", "assetId": "cmtudhpd8004etqf3ykpvgin7", "bgColor": ""}], "phoneHref": "", "statLabel": "", "statValue": "", "textAlign": "start", "categories": [], "kpiVariant": "counter-grid", "phoneLabel": "", "description": "", "heroVariant": "wave", "phoneNumber": "", "titleAccent": "", "itemCtaLabel": "", "marqueeItems": [], "processItems": [], "selectionMode": "latest", "bgImageAssetId": null, "primaryCtaHref": "", "primaryCtaLabel": "", "secondaryCtaHref": "", "testimonialItems": [], "secondaryCtaLabel": "", "selectedEntityIds": []}}', '2026-09-09 17:29:55.109', 'cmts0wj9r0000tqzz9audivoc');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtuic2ol009ztq2fih8lubig', 'cmtuic2ok009xtq2f7mhu18x2', 1, '{"bio": "<p>Muhammet Berat Arslan is the CEO and Full Stack &amp; Mobile Developer of Metro Yazılım. He develops scalable applications from architectural design to production using Flutter, React Native, React, NestJS, and TypeScript.</p><p>On the mobile side, he builds cross-platform applications with Flutter (GetX) and React Native (Expo), and develops authentication systems with Firebase Authentication and Twilio OTP. On the web side, he builds admin panels with a React SPA architecture and implements payment systems such as PayTR, İyzico, and Paynet along with shipping integrations. On the backend, he builds RESTful services on Node.js, NestJS, and PostgreSQL, and manages infrastructure and automation with Docker, Cloudflare, and n8n.</p><p>He places great importance on code review and team alignment, and additionally develops AI-powered agent capabilities for each integration.</p><p>Approach:</p><p>Taking an idea to production with a solid architecture and testing discipline.</p>", "name": "Muhammet Berat Arslan", "role": "CEO and Software Developer", "slug": "muhammet-berat-arslan", "email": "arslan@metroyazilim.com", "phone": null, "social": {"linkedin": "https://linkedin.com/in/arslanberatt", "instagram": "https://www.instagram.com/arslanberatt.m"}, "seoTitle": "Muhammet Berat Arslan", "imageAssetId": "cmtue5sd00078tqf3us2itse2", "seoDescription": "Muhammet Berat Arslan, CEO and Developer at Metro Yazılım"}', '2026-09-09 19:44:39.573', 'cmtuhhwl40000tq4znuptne60');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtuic2p200attq2flr3akta3', 'cmtuic2p200artq2f44gzpntx', 1, '{"bio": "<p>Anthon İkram Ümit is an international entrepreneur, business consultant, investor and producer working in the fields of capital, technology, construction, real estate, media and international business development.</p><p>With his background in trade, accounting, financial management, marketing, technology and film production, he built his career around identifying opportunities and bringing together the people, expertise and resources needed to advance them.</p><p>Working across different markets, particularly Australia, Turkey, the Middle East, Europe and the United States, he developed an international perspective on business, investment and strategic partnerships. His multicultural background and experience with English, Turkish, Kurdish, Japanese and Spanish support his ability to build relationships across different cultures and markets.</p><p>Rather than limiting himself to a single sector, he approaches opportunities from multiple angles—commercial, financial, technological, strategic and creative.</p><p>His philosophy is simple:</p><p><strong>Find the opportunity. Understand the value. Bring the right people together. Build something meaningful.</strong></p>", "name": "Anthon İkram Ümit", "role": "Co-Founder", "slug": "anthon-ikram-umit", "email": "umit@metroyazilim.com", "phone": null, "social": {"linkedin": "https://www.linkedin.com/in/anthonikramumit/", "instagram": "https://www.instagram.com/anthonikramumit"}, "seoTitle": null, "imageAssetId": "cmtue98nn0088tqf3gizb6h62", "seoDescription": "Anthon İkram Ümit, Founder of Metro Yazılım"}', '2026-09-09 19:44:39.591', 'cmtuhhwl40000tq4znuptne60');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtudlgzf005atqf38y550qat', 'cmtpkwkq0002ftq54d9ou1g6y', 1, '{"blocks": [], "widget": {"limit": 4, "title": "", "layout": "grid", "source": "services", "bgImage": null, "columns": "4", "imageAlt": "", "kpiItems": [], "partType": "collection", "subtitle": "", "checklist": [], "logoItems": [{"altText": "Isra Holding", "assetId": "cmtuchyiu001mtqf3dcwmkg9m", "bgColor": ""}, {"altText": "World Press Federation", "assetId": "cmtucjx7c001qtqf33e2ysrv9", "bgColor": ""}, {"altText": "1TVTR", "assetId": "cmtucq7x1002ctqf3kvhke134", "bgColor": ""}, {"altText": "Melbourne Films", "assetId": "cmtucs10w002mtqf32gvjwllw", "bgColor": "#000000"}, {"altText": "Istanbul Films", "assetId": "cmtud3bnf0038tqf3cw4gbvbh", "bgColor": "#000000"}, {"altText": "Elit Istanbul Tıp Merkezi", "assetId": "cmtud3svh003itqf3gbecj4mc", "bgColor": ""}, {"altText": "Guzuco", "assetId": "cmtudh61q003ytqf3d5n04iga", "bgColor": "#000000"}, {"altText": "Medipol", "assetId": "cmtudhpd8004etqf3ykpvgin7", "bgColor": ""}], "logoWidth": 420, "phoneHref": "", "statLabel": "", "statValue": "", "textAlign": "start", "categories": [], "kpiVariant": "counter-grid", "logoHeight": 160, "phoneLabel": "", "description": "", "heroVariant": "wave", "phoneNumber": "", "titleAccent": "", "itemCtaLabel": "", "marqueeItems": [], "processItems": [], "selectionMode": "latest", "bgImageAssetId": null, "primaryCtaHref": "", "primaryCtaLabel": "", "secondaryCtaHref": "", "testimonialItems": [], "secondaryCtaLabel": "", "selectedEntityIds": []}}', '2026-09-09 17:31:59.932', 'cmts0wj9r0000tqzz9audivoc');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtuic2pj00bntq2f0fcsvsbr', 'cmtuic2pi00bltq2f55egtn73', 1, '{"bio": "<p>CEO of Metro Yazılım. In the fields of product management, project management, and software development, I build end-to-end digital products from concept to launch. Muhammet Berat Arslan is the CEO and Full Stack &amp; Mobile Developer of Metro Yazılım. He develops scalable applications from architectural design to production using Flutter, React Native, React, NestJS, and TypeScript. On the mobile side, he builds cross-platform applications with Flutter (GetX) and React Native (Expo), and develops authentication systems with Firebase Authentication and Twilio OTP. On the web side, he builds admin panels with SPA architecture using React, and implements payment systems such as PayTR, İyzico, and Paynet along with shipping integrations. On the backend, he builds RESTful services on Node.js, NestJS, and PostgreSQL, and manages infrastructure and automation with Docker, Cloudflare, and n8n. He values code review and team alignment, and additionally develops AI-powered agent capabilities for each integration. His approach: carrying an idea into production with a solid architecture and testing discipline.</p>", "name": "Medine Nur Kara", "role": "Business Development & Sales", "slug": "medine-nur-kara", "email": "kara@metroyazilim.com", "phone": null, "social": {"linkedin": null, "instagram": "https://www.instagram.com/medinenurkara"}, "seoTitle": null, "imageAssetId": "cmtue052n0069tqf3ge7f63ol", "seoDescription": "CEO of Metro Yazılım. In the fields of product management, project management, and software development, I build end-to-end digital products from concept to launch."}', '2026-09-09 19:44:39.608', 'cmtuhhwl40000tq4znuptne60');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtudlyzh005itqf31y4xhn1w', 'cmtpkwkpx0024tq54isokx2ph', 1, '{"blocks": [], "widget": {"limit": 4, "title": "Teknolojiyi işe yarar ürünlere dönüştüren bir ekip", "layout": "grid", "source": "services", "bgImage": null, "columns": "4", "imageAlt": "Metro Yazılım ekibi", "kpiItems": [], "partType": "collection", "subtitle": "Hakkımızda", "checklist": ["İlk toplantıdan yayına kadar tek ekip", "Problemi anlar, doğru teknolojiyi seçeriz", "Zarif ve sürdürülebilir çözümler teslim ederiz"], "logoItems": [], "logoWidth": 300, "phoneHref": "tel:+905302518830", "statLabel": "Tamamlanan Proje", "statValue": "20+", "textAlign": "start", "categories": [], "kpiVariant": "counter-grid", "logoHeight": 100, "phoneLabel": "Bizi Hemen Arayın", "description": "Metro Yazılım; strateji, tasarım ve mühendisliği bir araya getirerek markaların dijital deneyimini uçtan uca kuruyor. Kısa vadeli çözümler değil, ölçeklenen ve zamanla büyüyen ürünler üretiyoruz.", "heroVariant": "wave", "phoneNumber": "+90 530 251 88 30", "titleAccent": "", "itemCtaLabel": "", "marqueeItems": [], "processItems": [], "selectionMode": "latest", "bgImageAssetId": "cmtudkusr0056tqf3mknm6e4d", "primaryCtaHref": "/iletisim", "primaryCtaLabel": "Hemen Başla", "secondaryCtaHref": "", "testimonialItems": [], "secondaryCtaLabel": "", "selectedEntityIds": []}}', '2026-09-09 17:32:23.261', 'cmts0wj9r0000tqzz9audivoc');
