INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtuic2w6001ytq58x3ffmxjr', 'cmtrwv4au0004tqdpqikux9nr', 1, '{"text": "<p>Strateji, tasarım ve mühendisliği bir araya getirerek markaların dijital deneyimini uçtan uca kuruyor. Kısa vadeli çözümler değil, ölçeklenen ve zamanla büyüyen ürünler üretiyoruz.</p><p>İlk toplantıdan yayına kadar tek bir ekip: problemi anlar, doğru teknolojiyi seçer ve zarif, sürdürülebilir çözümler teslim ederiz.</p>", "banner": "Hakkımızda", "marquee": ["Özel Yazılım", "Yapay Zekâ", "E-Ticaret"], "features": [{"text": "Girişimden kurumsala uçtan uca teslim edilen dijital ürünler.", "title": "20+ tamamlanan proje"}, {"text": "Dört kıtadaki ekiplerimizle teknolojiyi ihtiyaca göre şekillendiriyoruz.", "title": "6 global ofis"}], "seoTitle": "Hakkımızda", "subtitle": "Hakkımızda", "teamTitle": "İnovasyonun arkasındaki yüzler", "authorName": "Muhammet Berat Arslan", "authorRole": "CEO ve Yazılım Geliştirici", "collageAlt": "Metro Yazılım ekibi", "titleAfter": "dönüştüren bir ekip", "titleAccent": "ürünlere", "titleBefore": "Teknolojiyi işe yarar", "teamSubtitle": "Ekibimiz", "offeringTitle": "Uçtan uca dijital çözümler", "experienceUnit": "yıl", "offeringLabels": ["Web", "Mobil", "E-Ticaret", "Yapay Zekâ", "Bakım"], "seoDescription": "Metro Yazılım, özel yazılım, web siteleri, e-ticaret altyapıları, yapay zekâ otomasyonları geliştirerek işletmeleri daha hızlı, verimli ve yönetilebilir kılar.", "experienceLabel": "deneyim", "experienceValue": "1", "offeringSubtitle": "Sunduklarımız", "authorImageAssetId": "cmtue5sd00078tqf3us2itse2", "collageImageAssetId": "cmtudkusr0056tqf3mknm6e4d"}', '2026-09-09 19:44:39.846', 'cmts0wj9r0000tqzz9audivoc');
