INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtuicg6x0025tq581dsal29w', 'cmtrwv4au0006tqdp24ckcxq8', 1, '{"text": "<p>Our experienced team supports your business growth with the right strategies and modern technologies.</p>", "banner": "About Us", "marquee": ["Cybersecurity", "IT Solutions", "Technology", "Data Security"], "features": [{"text": "We deliver fast, lasting solutions to complex challenges.", "title": "Problem Solving"}, {"text": "We use technology to shape the future today.", "title": "Mission & Vision"}], "seoTitle": null, "subtitle": "ABOUT US", "teamTitle": "Meet Our Dedicated Team", "authorName": "Kaan Aksoy", "authorRole": "Co-Founder", "collageAlt": "Metro Yazılım specialists at work", "titleAfter": "to Increase Business Success", "titleAccent": "Technology", "titleBefore": "We Use", "teamSubtitle": "Team Members", "offeringTitle": "Lead the Way With Technology Trends", "experienceUnit": "Years", "offeringLabels": ["Website", "Android", "iOS", "Smartwatch", "IoT"], "seoDescription": null, "experienceLabel": "Experience", "experienceValue": "25", "offeringSubtitle": "What We Offer", "authorImageAssetId": null, "collageImageAssetId": "cmtudkusr0056tqf3mknm6e4d"}', '2026-09-09 19:44:57.081', 'cmts0wj9r0000tqzz9audivoc');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtudn1870060tqf3783is3nr', 'cmtpkwkq0002ftq54d9ou1g6y', 1, '{"blocks": [], "widget": {"limit": 4, "title": "", "layout": "grid", "source": "services", "bgImage": null, "columns": "4", "imageAlt": "", "kpiItems": [], "partType": "collection", "subtitle": "", "checklist": [], "logoItems": [{"altText": "Isra Holding", "assetId": "cmtuchyiu001mtqf3dcwmkg9m", "bgColor": ""}, {"altText": "World Press Federation", "assetId": "cmtucjx7c001qtqf33e2ysrv9", "bgColor": ""}, {"altText": "1TVTR", "assetId": "cmtucq7x1002ctqf3kvhke134", "bgColor": ""}, {"altText": "Melbourne Films", "assetId": "cmtucs10w002mtqf32gvjwllw", "bgColor": "#000000"}, {"altText": "Istanbul Films", "assetId": "cmtud3bnf0038tqf3cw4gbvbh", "bgColor": "#000000"}, {"altText": "Elit Istanbul Tıp Merkezi", "assetId": "cmtud3svh003itqf3gbecj4mc", "bgColor": ""}, {"altText": "Guzuco", "assetId": "cmtudh61q003ytqf3d5n04iga", "bgColor": "#000000"}, {"altText": "Medipol", "assetId": "cmtudhpd8004etqf3ykpvgin7", "bgColor": ""}], "logoWidth": 240, "phoneHref": "", "statLabel": "", "statValue": "", "textAlign": "start", "categories": [], "kpiVariant": "counter-grid", "logoHeight": 80, "phoneLabel": "", "description": "", "heroVariant": "wave", "phoneNumber": "", "titleAccent": "", "itemCtaLabel": "", "marqueeItems": [], "processItems": [], "selectionMode": "latest", "bgImageAssetId": null, "primaryCtaHref": "", "primaryCtaLabel": "", "secondaryCtaHref": "", "testimonialItems": [], "secondaryCtaLabel": "", "selectedEntityIds": []}}', '2026-09-09 17:33:12.824', 'cmts0wj9r0000tqzz9audivoc');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtuihnd60001tqbn6g7umdbw', 'cmtuic2hs000ttq2fjp6vdqy1', 2, '{"slug": "kurumsal-web-sitesi-yaptirirken-dikkat-edilmesi-gerekenler", "title": "Things to Consider When Building a Corporate Website", "author": "Berat", "blocks": [{"id": "b47", "html": "<p>Corporate websites are one of the most important parts of a business''s digital identity. A good website can make your brand look more professional and make it easier to reach potential customers. In this article, we will discuss the key factors that companies should pay attention to when having a corporate website built.</p>", "type": "text"}, {"id": "b48", "html": "<h3>The Importance of a Corporate Website</h3><p>A corporate website establishes your business''s online presence. Nowadays, people usually research products and services over the internet. Without a reliable website for your business, it becomes difficult to capture the attention of potential customers. In addition, your website also provides access to information about the products and services your company offers.</p>", "type": "text"}, {"id": "b49", "html": "<h3>The Necessity of Mobile-Friendly Design</h3><p>With the increasing use of mobile devices, it is essential that your website be mobile-friendly. Mobile-friendly design improves user experience and is favored by search engines. Search engines like Google prioritize mobile-friendly sites, so responsive design should be preferred.</p>", "type": "text"}, {"id": "b50", "html": "<h3>The Importance of Page Speed</h3><p>Fast loading of your website is a critical factor for user experience. Users can quickly abandon slow-loading pages. Additionally, page speed is also an influential factor for SEO, as search engines rank fast sites higher. Methods such as optimizing images and removing unnecessary plugins can be used to increase page speed.</p>", "type": "text"}, {"id": "b51", "html": "<h3>Design That Builds Trust</h3><p>Your website''s design should reflect your brand''s identity and inspire trust in visitors. Colors, fonts, and overall design harmony affect the trust potential customers place in your company. A professional design encourages users to spend more time on your site and increases conversion rates.</p>", "type": "text"}, {"id": "b52", "html": "<h3>Contact Information and Conversion Areas</h3><p>You should clearly share your contact information so that users can quickly get in touch with you. Conversion-focused elements such as a quote form, phone number, or email make it easier for potential customers to connect with you. These elements need to be prominently displayed.</p>", "type": "text"}, {"id": "b53", "html": "<h3>Why Is SEO Infrastructure Important?</h3><p>Properly setting up SEO infrastructure increases your website''s visibility in search engines. Effective use of keywords helps your site attract more visitors.</p>", "type": "text"}, {"id": "b54", "html": "<h3>What Is an Admin Panel?</h3><p>An admin panel allows you to easily update your website''s content. A user-friendly panel makes managing your content easier.</p>", "type": "text"}, {"id": "b55", "html": "<h3>What Security Measures Should Be in Place?</h3><p>An SSL certificate enhances the security of your website. Basic maintenance support is also important for protecting users'' data.</p>", "type": "text"}, {"id": "b56", "html": "<h3>References and About Us Page</h3><p>Correctly presenting your references and services on your website helps potential customers gain trust. The About Us page informs visitors by providing information about your company''s history and mission. These pages reflect your company''s professionalism.</p>", "type": "text"}, {"id": "b57", "html": "<h3>Conclusion</h3><p>In conclusion, a corporate website is not just a visual tool but also a platform that brings in customers. The factors to consider are vital to the success of your website. The combination of professional web design and the right strategies will make your brand stand out in the online world.</p><p>Contact Metro Yazılım to design your corporate website. Our expert team offers solutions tailored to your needs.</p>", "type": "text"}], "excerpt": "Corporate websites are one of the most important parts of a business''s digital identity. A good website can make your brand look more professional and make it easier to reach potential customers.", "category": "Web Design", "seoTitle": "Things to Consider When Building a Corporate Website", "seoDescription": "Information on the key factors that companies should consider when having a corporate website built.", "coverImageAssetId": null}', '2026-09-09 19:48:59.659', 'cmtuhhwl40000tq4znuptne60');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtuihne3000ptqbnjibevbbg', 'cmtuic2jv003btq2fhw06uaas', 2, '{"slug": "voltstep-sports-cok-modullu-e-ticaret-platformu", "title": "VoltStep Sports: Multi-Module E-Commerce Platform", "client": null, "category": "E-Commerce", "seoTitle": "VoltStep Sports: E-Commerce Platform Development", "seoDescription": "VoltStep Sports offers a secure online shopping experience with its multi-module e-commerce platform. Built with custom e-commerce software.", "solutionBlocks": [{"id": "b32", "html": "<p>VoltStep Sports was designed as a comprehensive e-commerce platform. A system was built that unifies critical processes such as product, variant, and stock management within a single infrastructure. This system meets user needs by offering dynamically manageable product attributes and a comprehensive data structure.</p><p>VoltStep Sports was developed as a mobile-friendly customer storefront using React 19 and Tailwind CSS. This allows users to access the platform comfortably from any device. Virtualized listing technology was used to ensure performance with large product lists, minimizing page load times.</p><p>The project is supported by a scalable, centralized backend architecture based on NestJS. Using PostgreSQL and Prisma, a comprehensive data structure with more than 40 models was created. An EAV-based attribute system was developed for dynamic product management. As a result, an infrastructure for color-based variants, stock, pricing, and image definitions was integrated into the products.</p><p>The admin panel was developed using React 19, Vite, and TanStack Query. Users can easily manage product and category administration, as well as campaign and pricing processes. In addition, drag-and-drop features enable category, brand, collection, and tag management. Critical operations are logged with AuditLog, enhancing security.</p><p>The cart and order creation flows were carefully developed to make the shopping experience easier for users. A secure online payment infrastructure was established with PayTR integration. In addition, a rating and review system for purchased products allows the collection of user feedback. Post-order return and exchange processes were also incorporated into the system to provide flexibility.</p><p>A dedicated support ticket system was created to track customer requests. This system offers a platform where users can quickly submit their questions and issues. In addition, thanks to an i18next-based localization system for multi-language support, service is provided in different languages.</p><p>A notification infrastructure was developed for both users and staff. Thanks to this system, important updates and notifications are delivered instantly. Users are informed about order statuses, while staff can receive alerts for critical tasks.</p><p>In the project, a webhook infrastructure was prepared to allow external systems to connect. API documentation for the backend services was created with Swagger, making it easier for developers to access the API. In addition, order documents are generated automatically with a PDF generation system.</p><p>As a result, VoltStep Sports was delivered as a user-friendly and comprehensive e-commerce platform that brings together various modules. All processes, from the customer storefront to the admin panel, and from the backend API to the data structure, were developed as an integrated whole, resulting in a system that meets all requirements.</p>", "type": "text"}], "challengeBlocks": [{"id": "b31", "html": "<p>Due to the limited features of the existing e-commerce system, the client aimed to increase efficiency and improve the user experience. Product, variant, stock, campaign, and payment processes needed to be managed within an integrated structure. Establishing a robust system that would allow users to easily carry out post-purchase return and exchange processes was also identified as an important need.</p>", "type": "text"}], "galleryAssetIds": [], "coverImageAssetId": null}', '2026-09-09 19:48:59.692', 'cmtuhhwl40000tq4znuptne60');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtuihnet001dtqbn6f2twpna', 'cmtuic2mb006ltq2fvg0ojcea', 2, '{"icon": null, "slug": "mobil-uygulama-gelistirme-hizmetleri", "title": "Mobile Application Development Services", "blocks": [{"id": "b11", "html": "<p>Mobile application development is a process that enables businesses and entrepreneurs to bring their products or services to mobile devices. Today, the importance of mobile applications is steadily growing, offering solutions that improve user experience and increase engagement. At Metro Yazılım, we design and develop user-focused, fast, and secure mobile applications.</p><p>At the end of the mobile application development process, we deliver a user-friendly, fast, and secure mobile application. We also simplify user and content management processes with an integrated management panel. Your application is delivered ready to be published on both the App Store and Google Play.</p>", "type": "text"}, {"id": "b12", "html": "<h3>Who it''s suitable for</h3><ul><li>Businesses wanting to bring their products or services to mobile devices</li><li>Startups and entrepreneurs</li><li>E-commerce companies</li><li>Service providers</li><li>Corporate companies seeking mobile solutions for their employees</li></ul>", "type": "text"}, {"id": "b13", "html": "<h3>What it covers</h3><ul><li>E-commerce applications</li><li>Reservation applications</li><li>Corporate applications</li><li>Customer applications</li><li>Mobile systems for field teams</li><li>Membership and subscription applications</li></ul>", "type": "text"}, {"id": "b14", "html": "<h3>How we work</h3><ul><li>We analyze the mobile application idea and target user audience.</li><li>We determine the core features and user flows of the application.</li><li>We develop solutions with a shared codebase for iOS and Android.</li><li>We design modern and user-friendly mobile interfaces.</li><li>We build user registration, login, and authorization systems.</li><li>We integrate notification, location, camera, payment, and file upload features.</li><li>We develop a web-based management panel to manage the mobile application.</li><li>We prepare the backend API and database infrastructure.</li><li>We test the application on different screen sizes and devices.</li><li>We perform performance, data security, and error checks.</li><li>We provide support during App Store and Google Play publishing processes.</li><li>After launch, we provide maintenance, updates, and new feature development services.</li></ul>", "type": "text"}, {"id": "b15", "html": "<h3>Technologies we use</h3><ul><li>Flutter: A fast and effective application development tool for both iOS and Android.</li><li>React Native: A framework used for cross-platform application development.</li><li>Firebase: Provides real-time database and user authentication services.</li><li>Node.js: Used to develop fast and scalable applications on the server side.</li><li>NestJS: A powerful server application framework.</li><li>TypeScript: A superset of JavaScript that makes application development safer.</li><li>PostgreSQL: A powerful and reliable relational database management system.</li><li>REST API: A standard method for exchanging data between applications.</li><li>Cloud services: Offer flexible solutions for hosting and scaling your applications.</li></ul>", "type": "text"}], "summary": "We develop high-performance, secure, and user-focused mobile applications for iOS and Android devices. We manage the entire process from the idea stage to store publishing and maintenance.", "seoTitle": "Mobile Application Development", "imageAssetId": null, "seoDescription": "Metro Yazılım offers modern mobile application development services for iOS and Android. Bring your business to the mobile platform."}', '2026-09-09 19:48:59.718', 'cmtuhhwl40000tq4znuptne60');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtuihnfc0021tqbnw7gkchw3', 'cmtuic2ok009xtq2f7mhu18x2', 1, '{"bio": "<p>Muhammet Berat Arslan is the CEO and Full Stack &amp; Mobile Developer of Metro Yazılım. He develops scalable applications from architectural design to production using Flutter, React Native, React, NestJS, and TypeScript.</p><p>On the mobile side, he builds cross-platform applications with Flutter (GetX) and React Native (Expo), and develops authentication systems with Firebase Authentication and Twilio OTP. On the web side, he builds admin panels with a React SPA architecture and implements payment systems such as PayTR, İyzico, and Paynet along with shipping integrations. On the backend, he builds RESTful services on Node.js, NestJS, and PostgreSQL, and manages infrastructure and automation with Docker, Cloudflare, and n8n.</p><p>He places great importance on code review and team alignment, and additionally develops AI-powered agent capabilities for each integration.</p><p>Approach:</p><p>Taking an idea to production with a solid architecture and testing discipline.</p>", "name": "Muhammet Berat Arslan", "role": "CEO and Software Developer", "slug": "muhammet-berat-arslan", "email": "arslan@metroyazilim.com", "phone": null, "social": {"linkedin": "https://linkedin.com/in/arslanberatt", "instagram": "https://www.instagram.com/arslanberatt.m"}, "seoTitle": "Muhammet Berat Arslan", "imageAssetId": "cmtue5sd00078tqf3us2itse2", "seoDescription": "Muhammet Berat Arslan, CEO and Developer at Metro Yazılım"}', '2026-09-09 19:48:59.736', 'cmtuhhwl40000tq4znuptne60');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtuihnfu002ptqbngvjgg959', 'cmtuic2pi00bltq2f55egtn73', 1, '{"bio": "<p>CEO of Metro Yazılım. In the fields of product management, project management, and software development, I build end-to-end digital products from concept to launch. Muhammet Berat Arslan is the CEO and Full Stack &amp; Mobile Developer of Metro Yazılım. He develops scalable applications from architectural design to production using Flutter, React Native, React, NestJS, and TypeScript. On the mobile side, he builds cross-platform applications with Flutter (GetX) and React Native (Expo), and develops authentication systems with Firebase Authentication and Twilio OTP. On the web side, he builds admin panels with SPA architecture using React, and implements payment systems such as PayTR, İyzico, and Paynet along with shipping integrations. On the backend, he builds RESTful services on Node.js, NestJS, and PostgreSQL, and manages infrastructure and automation with Docker, Cloudflare, and n8n. He values code review and team alignment, and additionally develops AI-powered agent capabilities for each integration. His approach: carrying an idea into production with a solid architecture and testing discipline.</p>", "name": "Medine Nur Kara", "role": "Business Development & Sales", "slug": "medine-nur-kara", "email": "kara@metroyazilim.com", "phone": null, "social": {"linkedin": null, "instagram": "https://www.instagram.com/medinenurkara"}, "seoTitle": null, "imageAssetId": "cmtue052n0069tqf3ge7f63ol", "seoDescription": "CEO of Metro Yazılım. In the fields of product management, project management, and software development, I build end-to-end digital products from concept to launch."}', '2026-09-09 19:48:59.755', 'cmtuhhwl40000tq4znuptne60');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtue5bhi0070tqf3af7drpfv', 'cmtue5bh6006ytqf3ah1xdsze', 1, '{"bio": "<p>Muhammet Berat Arslan, Metro Yazılım''ın CEO''su ve Full Stack &amp; Mobil Geliştiricisi''dir. Flutter, React Native, React, NestJS ve TypeScript ile mimari tasarımdan production''a kadar ölçeklenebilir uygulamalar geliştirir.</p><p>Mobil tarafta Flutter (GetX) ve React Native (Expo) ile cross-platform uygulamalar kurar; Firebase Authentication ve Twilio OTP ile kimlik doğrulama sistemleri geliştirir. Web tarafında React ile SPA mimarisinde admin panelleri inşa eder, PayTR, İyzico ve Paynet gibi ödeme sistemlerini kargo entegrasyonlarıyla birlikte hayata geçirir. Backend''de Node.js, NestJS ve PostgreSQL üzerine RESTful servisler kurar; Docker, Cloudflare ve n8n ile altyapı ve otomasyonu yönetir.</p><p>Kod incelemesine ve ekip içi uyuma önem verir; entegrasyonların her biri için ayrıca yapay zekâ destekli ajan yetenekleri geliştirir. Yaklaşımı: fikri production''a, sağlam bir mimariyle ve test disipliniyle taşımak.</p>", "name": "Muhammet Berat Arslan", "role": "CEO ve Yazılım Geliştirici", "slug": "muhammet-berat-arslan", "email": null, "phone": null, "social": null, "seoTitle": null, "imageAssetId": null, "seoDescription": null}', '2026-09-09 17:47:25.927', 'cmts0wj9r0000tqzz9audivoc');
