INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtuen2mj00aotqf3kaiut5l9', 'cmtuegjhy0001tq9r7grg0xer', 1, '{"bio": "<p>Finans, teknoloji, medya, gayrimenkul ve uluslararası iş geliştirme alanlarında çalışan uluslararası girişimci, yatırımcı ve danışman. Ticaret, muhasebe, finansal yönetim, pazarlama, teknoloji ve film prodüksiyonu alanlarındaki birikimiyle kariyerini fırsatları görmek ve o fırsatları ileri taşıyacak insanları, uzmanlığı ve kaynakları bir araya getirmek üzerine kurdu. Avustralya, Türkiye, Orta Doğu, Avrupa ve Amerika Birleşik Devletleri başta olmak üzere farklı pazarlarda çalışarak iş, yatırım ve stratejik ortaklıklar konusunda uluslararası bir bakış açısı geliştirdi. Çok kültürlü geçmişi ve İngilizce, Türkçe, Kürtçe, Japonca ile İspanyolca dil deneyimi, farklı kültürler ve pazarlarda ilişki kurabilmesini destekliyor. Kendini tek bir sektörle sınırlamak yerine fırsatlara ticari, finansal, teknolojik, stratejik ve yaratıcı olmak üzere birden fazla açıdan yaklaşıyor. Felsefesi basit: Fırsatı bul. Değeri anla. Doğru insanları buluştur. Anlamlı bir şey inşa et.</p>", "name": "Anthon İkram Ümit", "role": "Co-Founder", "slug": "anthon-ikram-umit", "email": null, "phone": null, "social": {"linkedin": "https://www.linkedin.com/in/anthonikramumit/", "instagram": "https://www.instagram.com/anthonikramumit"}, "seoTitle": null, "imageAssetId": "cmtue98nn0088tqf3gizb6h62", "seoDescription": "Finans, teknoloji, medya, gayrimenkul ve uluslararası iş geliştirme alanlarında çalışan uluslararası girişimci, yatırımcı ve danışman.\r\n\r\nTicaret, muhasebe, finan"}', '2026-09-09 18:01:14.252', 'cmts0wj9r0000tqzz9audivoc');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtuenh5o00autqf33c8gq8t7', 'cmtuegjhy0001tq9r7grg0xer', 1, '{"bio": "<p>Anthon İkram Ümit; sermaye, teknoloji, inşaat, gayrimenkul, medya ve uluslararası iş geliştirme alanlarında çalışan uluslararası bir girişimci, iş danışmanı, yatırımcı ve yapımcıdır.</p><p>Ticaret, muhasebe, finansal yönetim, pazarlama, teknoloji ve film prodüksiyonu alanlarındaki birikimiyle kariyerini fırsatları görmek ve o fırsatları ileri taşıyacak insanları, uzmanlığı ve kaynakları bir araya getirmek üzerine kurdu.</p><p>Avustralya, Türkiye, Orta Doğu, Avrupa ve Amerika Birleşik Devletleri başta olmak üzere farklı pazarlarda çalışarak iş, yatırım ve stratejik ortaklıklar konusunda uluslararası bir bakış açısı geliştirdi. Çok kültürlü geçmişi ve İngilizce, Türkçe, Kürtçe, Japonca ile İspanyolca dil deneyimi, farklı kültürler ve pazarlarda ilişki kurabilmesini destekliyor.</p><p>Kendini tek bir sektörle sınırlamak yerine fırsatlara ticari, finansal, teknolojik, stratejik ve yaratıcı olmak üzere birden fazla açıdan yaklaşıyor. </p><p>Felsefesi basit: </p><p><strong>Fırsatı bul. Değeri anla. Doğru insanları buluştur. Anlamlı bir şey inşa et.</strong></p>", "name": "Anthon İkram Ümit", "role": "Co-Founder", "slug": "anthon-ikram-umit", "email": null, "phone": null, "social": {"linkedin": "https://www.linkedin.com/in/anthonikramumit/", "instagram": "https://www.instagram.com/anthonikramumit"}, "seoTitle": null, "imageAssetId": "cmtue98nn0088tqf3gizb6h62", "seoDescription": "Finans, teknoloji, medya, gayrimenkul ve uluslararası iş geliştirme alanlarında çalışan uluslararası girişimci, yatırımcı ve danışman.\r\n\r\nTicaret, muhasebe, finan"}', '2026-09-09 18:01:33.085', 'cmts0wj9r0000tqzz9audivoc');
