INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtuewdh800e3tqf30jt87iwt', 'cmtue5bh6006ytqf3ah1xdsze', 1, '{"bio": "<p>Muhammet Berat Arslan, Metro Yazılım''ın CEO''su ve Full Stack &amp; Mobil Geliştiricisi''dir. Flutter, React Native, React, NestJS ve TypeScript ile mimari tasarımdan production''a kadar ölçeklenebilir uygulamalar geliştirir.</p><p>Mobil tarafta Flutter (GetX) ve React Native (Expo) ile cross-platform uygulamalar kurar; Firebase Authentication ve Twilio OTP ile kimlik doğrulama sistemleri geliştirir. Web tarafında React ile SPA mimarisinde admin panelleri inşa eder, PayTR, İyzico ve Paynet gibi ödeme sistemlerini kargo entegrasyonlarıyla birlikte hayata geçirir. Backend''de Node.js, NestJS ve PostgreSQL üzerine RESTful servisler kurar; Docker, Cloudflare ve n8n ile altyapı ve otomasyonu yönetir.</p><p>Kod incelemesine ve ekip içi uyuma önem verir; entegrasyonların her biri için ayrıca yapay zekâ destekli ajan yetenekleri geliştirir. </p><p>Yaklaşım: </p><p>Fikri production''a, sağlam bir mimariyle ve test disipliniyle taşımak.</p>", "name": "Muhammet Berat Arslan", "role": "CEO ve Yazılım Geliştirici", "slug": "muhammet-berat-arslan", "email": "arslan@metroyazilim.com", "phone": null, "social": {"linkedin": "https://linkedin.com/in/arslanberatt", "instagram": "https://www.instagram.com/arslanberatt.m"}, "seoTitle": "Muhammet Berat Arslan", "imageAssetId": "cmtue5sd00078tqf3us2itse2", "seoDescription": "Metro Yazılım CEO ve Yazılımcısı Muhammet Berat Arslan"}', '2026-09-09 18:08:28.22', 'cmts0wj9r0000tqzz9audivoc');
INSERT INTO public."ContentTranslationRevision" (id, "translationId", "schemaVersion", payload, "createdAt", "createdBy") VALUES ('cmtueyhag00eotqf3biw741ed', 'cmtue5bh6006ytqf3ah1xdsze', 1, '{"bio": "<p>Muhammet Berat Arslan, Metro Yazılım''ın CEO''su ve Full Stack &amp; Mobil Geliştiricisi''dir. Flutter, React Native, React, NestJS ve TypeScript ile mimari tasarımdan production''a kadar ölçeklenebilir uygulamalar geliştirir.</p><p>Mobil tarafta Flutter (GetX) ve React Native (Expo) ile cross-platform uygulamalar kurar; Firebase Authentication ve Twilio OTP ile kimlik doğrulama sistemleri geliştirir. Web tarafında React ile SPA mimarisinde admin panelleri inşa eder, PayTR, İyzico ve Paynet gibi ödeme sistemlerini kargo entegrasyonlarıyla birlikte hayata geçirir. Backend''de Node.js, NestJS ve PostgreSQL üzerine RESTful servisler kurar; Docker, Cloudflare ve n8n ile altyapı ve otomasyonu yönetir.</p><p>Kod incelemesine ve ekip içi uyuma önem verir; entegrasyonların her biri için ayrıca yapay zekâ destekli ajan yetenekleri geliştirir. </p><p>Yaklaşım: </p><p><strong>Fikri production''a, sağlam bir mimariyle ve test disipliniyle taşımak.</strong></p>", "name": "Muhammet Berat Arslan", "role": "CEO ve Yazılım Geliştirici", "slug": "muhammet-berat-arslan", "email": "arslan@metroyazilim.com", "phone": null, "social": {"linkedin": "https://linkedin.com/in/arslanberatt", "instagram": "https://www.instagram.com/arslanberatt.m"}, "seoTitle": "Muhammet Berat Arslan", "imageAssetId": "cmtue5sd00078tqf3us2itse2", "seoDescription": "Metro Yazılım CEO ve Yazılımcısı Muhammet Berat Arslan"}', '2026-09-09 18:10:06.472', 'cmts0wj9r0000tqzz9audivoc');
